1	// A discrete-event simulator of the tasks-dispatch spec (DESIGN.md), so the
2	// scenario play-throughs in the canon's SCENARIOS record are executable instead of prose-only.
3	//
4	// What it models faithfully: virtual time; the scheduler run as a STATELESS
5	// loop (docs/PRINCIPLES.md) — at every tick it asks every task ON THE SCHEDULE
6	// (one stating a condition, none of which reads the item itself; a task stating
7	// none runs only from an item somebody created, at whose pick an empty
8	// expression holds), through the task's own preconditions: the run-history
9	// terms first (`due:`, `last-run-over:`, `last-run-not-failed`), judged over
10	// the task's own items in the issue store, then the scenario's precondition
11	// function standing for every other condition; a yes files a READY item, a no
12	// is a log line and nothing else, a read the scheduler cannot make fails OPEN —
13	// and the engine's one invariant, ONE LIVE ITEM PER TASK, with the F16 dedupe
14	// of live duplicates; readiness; adoption; the executing-leash reclaim), the
15	// executor loop (pick order, same-title mutex, the `schedule_after` yield,
16	// claim, validate, the pick-time re-evaluation over the item's OWN facts — a
17	// woken item satisfies the cadence terms — whose no-go CLOSES the item, the
18	// work step/hand-off/converge as timed phases, heartbeat comments during the
19	// work step so the leash measures executor death rather than work duration),
20	// at-most-once invocation (one call per item, never retried — the
21	// fired/refused/unanswered trichotomy, docs/PRINCIPLES.md), readiness as the
22	// scheduler run's alone (F1, reopened 2026-08-15, then reversed 2026-08-26 /
23	// #1373), the janitor's stale-ready escalation, and the force lever (waking
24	// where an item exists, minting where none does — both stamped `Woken`, which
25	// is what the cadence terms read at pick).
26	//
27	// The engine keeps NO memory of an ask: there is no schedule board, no
28	// watermark, no first-window booking and no migration here because there is
29	// none in `queue/scheduler-run.mjs` — a decline is asked again at the next
30	// tick, and the only record of one is the `ask` log entry this model writes for
31	// the line the real run prints.
32	//
33	// What it deliberately does NOT model is inventoried in README.md's "The
34	// unsimulated world" — one row per boundary (cron delivery, list freshness,
35	// label non-atomicity, comment-id ordering, event delivery, secrets, …) with
36	// what defends the design there. A bug living exactly on one of those
37	// boundaries will not surface here; executor contention IS modeled, as
38	// stale-snapshot races over the claim protocol (raceExecutorsAt).
39	//
40	// Time is milliseconds UTC; events run strictly in time order (FIFO within a
41	// tie). Nothing here sleeps, threads, or reads the wall clock.
42	
43	const MIN = 60_000;
44	const HOUR = 60 * MIN;
45	const DAY = 24 * HOUR;
46	
47	export const T = (iso) => Date.parse(iso.length === 17 ? iso.replace('Z', ':00Z') : iso);
48	const iso = (t) => new Date(t).toISOString().slice(0, 16) + 'Z';
49	
50	// ---- the calendar (calendar.mjs, queue/anchors.mjs) --------------------------
51	// The cadence vocabulary a task states INSIDE its preconditions, and the anchor
52	// arithmetic a `due:` term measures the run history against. Daily anchors at
53	// 04:00Z, weekly at Sunday 04:00Z, monthly on the 1st at 04:00Z — the schedule
54	// defaults. mostRecentAnchor is the latest anchor ≤ now.
55	export const CADENCES = ['daily', 'weekly', 'monthly'];
56	export const DUE_TERM = 'due';
57	export const ELAPSED_TERM = 'last-run-over';
58	export const NOT_FAILED_TERM = 'last-run-not-failed';
59	// The terms that read the item itself (precondition-policy.mjs `needsItem`):
60	// only the request task's `request-eligible`. The scheduler's own ask has no
61	// item to judge such a term against, so a task stating one is off the schedule.
62	export const ITEM_TERMS = new Set(['request-eligible']);
63	// How far back the run history reaches (signals/index.mjs RUN_HORIZON_DAYS): a
64	// task with no run inside it reads as never having run.
65	export const RUN_HORIZON_DAYS = 40;
66	
67	const ANCHOR_HOUR = 4;
68	
69	export function periodMs(cadence) {
70	  if (cadence === 'weekly') return 7 * DAY;
71	  if (cadence === 'monthly') return 31 * DAY;
72	  if (cadence === 'daily') return DAY;
73	  throw new Error(`no period for ${cadence}`);
74	}
75	
76	export function mostRecentAnchor(cadence, now) {
77	  if (!CADENCES.includes(cadence)) throw new Error(`no anchor for ${cadence}`);
78	  const d = new Date(now);
79	  let a = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate(), ANCHOR_HOUR);
80	  if (a > now) a -= DAY;
81	  if (cadence === 'weekly') {
82	    while (new Date(a).getUTCDay() !== 0 || a > now) a -= DAY;
83	  }
84	  // Monthly: day 1 at the anchor hour, walking back a month when this month's has not come.
85	  if (cadence === 'monthly') {
86	    const d2 = new Date(a);
87	    a = Date.UTC(d2.getUTCFullYear(), d2.getUTCMonth(), 1, ANCHOR_HOUR);
88	    if (a > now) {
89	      const back = new Date(a);
90	      a = Date.UTC(back.getUTCFullYear(), back.getUTCMonth() - 1, 1, ANCHOR_HOUR);
91	    }
92	  }
93	  return a;
94	}
95	
96	// `12h`, `1d`, `7d` — a whole number of hours or days, nothing else.
97	export function parseDuration(text) {
98	  const m = /^(\d+)(h|d)$/.exec(String(text ?? ''));
99	  if (!m) return null;
100	  const n = Number(m[1]);
101	  return n > 0 ? n * (m[2] === 'h' ? HOUR : DAY) : null;
102	}
103	
104	// The grammar precondition-policy.mjs parses: entries are conjuncts, `||`
105	// separates alternatives inside one, the argument follows the first colon.
106	const alternativesOf = (entry) => String(entry ?? '').split('||').map((t) => t.trim()).filter(Boolean)
107	  .map((t) => { const c = t.indexOf(':'); return c === -1 ? { name: t, arg: null, text: t } : { name: t.slice(0, c).trim(), arg: t.slice(c + 1).trim(), text: t }; });
108	const entriesOf = (preconditions) => (Array.isArray(preconditions) ? preconditions : []).map(alternativesOf);
109	
110	// The cadence a declaration states — the first cadence term wins; null for a
111	// task with no cadence term (calendar.mjs cadenceOf).
112	export function cadenceOf(preconditions) {
113	  for (const ref of entriesOf(preconditions).flat()) {
114	    if (ref.name === DUE_TERM && CADENCES.includes(ref.arg)) return { kind: 'due', cadence: ref.arg };
115	    if (ref.name === ELAPSED_TERM) {
116	      const ms = parseDuration(ref.arg);
117	      if (ms) return { kind: 'elapsed', ms, text: ref.arg };
118	    }
119	  }
120	  return null;
121	}
122	
123	// Whether the declaration states any condition at all (calendar.mjs
124	// statesConditions). Not a scheduling answer on its own: it is what the door
125	// below reads to derive a trigger for a declaration stating none.
126	export const statesConditions = (preconditions) => entriesOf(preconditions).length > 0;
127	
128	export const TRIGGER_SCHEDULE = 'schedule';
129	export const TRIGGER_REQUEST = 'request';
130	
131	// ON THE SCHEDULE (task-contract.mjs isScheduledTask): the declaration says so.
132	// The sim models what the ENGINE WRITES, and what the engine now writes into a
133	// planned item is decided by this field alone — with no terms to load and no
134	// shape to interpret, which is the point of the field.
135	export const isScheduled = (decl) => decl?.trigger === TRIGGER_SCHEDULE;
136	
137	// The period a TASK keeps (queue/anchors.mjs taskPeriodMs): its `due:` cadence's
138	// period, its `last-run-over:` duration, null for a task with no cadence term.
139	export const taskPeriodMs = (preconditions) => {
140	  const cadence = cadenceOf(preconditions);
141	  if (cadence?.kind === 'due') return periodMs(cadence.cadence);
142	  if (cadence?.kind === 'elapsed') return cadence.ms;
143	  return null;
144	};
145	
146	// THE FREQUENCY DOOR (task-contract.mjs normalizeTaskDeclaration). `frequency`
147	// is retired: a declaration still carrying it reads as the cadence term it
148	// always meant, first in the expression, and a `none` beside it drops. A
149	// retired spelling (`hourly`, `daily-2h`) is refused outright — the legacy map
150	// is empty (#1234) — where the engine's declaration check would refuse it at
151	// authoring time.
152	export const FREQUENCIES = ['daily', 'weekly', 'monthly', 'manual'];
153	// What the field always meant, as the term that now says it — or null for
154	// `manual`, which meant no schedule at all and so adds no term.
155	export const cadenceTermFor = (frequency) => (frequency === 'manual' ? null : `${DUE_TERM}:${frequency}`);
156	
157	// The load point — the sim's equivalent of `normalizeTaskDeclaration` plus the
158	// declaration check. The sim's `preconditions` carries the run-history terms it
159	// evaluates itself, plus an item-reading term the scenario's `precondition`
160	// function stands for; that function stands for every other condition the real
161	// declaration would name too, so a term outside that vocabulary is a scenario
162	// error here rather than a fail-open.
163	export function loadDeclaration(decl) {
164	  const out = { ...decl };
165	  if (out.frequency !== undefined) {
166	    if (!FREQUENCIES.includes(out.frequency)) {
167	      throw new Error(`${out.id}: "${out.frequency}" is not a frequency the door accepts — a retired spelling is refused, not normalized`);
168	    }
169	    const stated = (Array.isArray(out.preconditions) ? out.preconditions : []).filter((e) => String(e).trim() !== 'none');
170	    const term = cadenceTermFor(out.frequency);
171	    out.preconditions = term === null || stated.some((e) => String(e).trim() === term) ? stated : [term, ...stated];
172	    delete out.frequency;
173	  }
174	  // THE TRIGGER DOOR, as the contract runs it: stated wins, and a declaration
175	  // stating none is read off the shape of its conditions — a term reading the item
176	  // has nothing to judge at a tick, so it keeps the task off the schedule.
177	  if (out.trigger === undefined) {
178	    out.trigger = statesConditions(out.preconditions)
179	      && !entriesOf(out.preconditions).flat().some((ref) => ITEM_TERMS.has(ref.name))
180	      ? TRIGGER_SCHEDULE : TRIGGER_REQUEST;
181	  } else if (![TRIGGER_SCHEDULE, TRIGGER_REQUEST].includes(out.trigger)) {
182	    throw new Error(`${out.id}: "${out.trigger}" is not a trigger the contract accepts`);
183	  }
184	  // An absent `preconditions` stays absent, as through the engine's door; the
