212	  const woken = item?.woken === true;
213	  const newest = runs[0] ?? null;
214	  if (ref.name === DUE_TERM) {
215	    if (woken) return { holds: true, reason: `#${item.number} was woken by hand — the wake stands in for the cadence` };
216	    const anchor = mostRecentAnchor(ref.arg, now);
217	    // Both halves of the old occurrence guard (F13): an item CREATED since the
218	    // anchor is this period's, and so is one CLOSED since it.
219	    const since = runs.find((r) => r.createdAt >= anchor || (r.closedAt ?? -Infinity) >= anchor);
220	    return since
221	      ? { holds: false, reason: `#${since.number} already ran since the ${ref.arg} anchor at ${iso(anchor)}` }
222	      : { holds: true, reason: `no run since the ${ref.arg} anchor at ${iso(anchor)}` };
223	  }
224	  if (ref.name === ELAPSED_TERM) {
225	    if (woken) return { holds: true, reason: `#${item.number} was woken by hand — the wake stands in for the cadence` };
226	    if (!newest) return { holds: true, reason: `no run of this task in the last ${RUN_HORIZON_DAYS} days` };
