240	// The conjunction: every entry needs one holding alternative. The scenario's
241	// precondition function is a further conjunct the caller judges after this one
242	// says yes — exactly the engine's two-pass ask — and it is also what stands for
243	// an item-reading term, so that conjunct is left to it. An empty expression
244	// holds: the item itself is the ask.
245	export function judgeHistory(preconditions, runs, item, now) {
246	  const held = [];
247	  let delegated = false;
248	  for (const alts of entriesOf(preconditions)) {
249	    if (alts.length === 1 && ITEM_TERMS.has(alts[0].name)) { delegated = true; continue; }
250	    const outs = alts.map((ref) => termHolds(ref, runs, item, now));
251	    const winner = outs.find((o) => o.holds);
252	    if (!winner) return { run: false, reason: outs.map((o) => o.reason).join('; nor ') };
253	    held.push(winner.reason);
254	  }
255	  if (held.length) return { run: true, reason: held.join('; ') };
256	  return { run: true, reason: delegated ? '' : 'no conditions stated — the item itself is the ask' };
