577	  // verdict is that item's problem, never the executor's; only the tick-side
578	  // ask fails open.
579	  function askAtPick(task, it) {
580	    const history = judgeHistory(task.preconditions, runsOf(it.taskId, it.number), itemFacts(it), now);
581	    if (!history.run) return history;
582	    if (!task.precondition) return { run: true, reason: history.reason };
583	    let verdict;
584	    try { verdict = task.precondition(world, now, it, windowOf(task, it.number)) ?? {}; }
585	    catch (e) { return { run: false, reason: `precondition threw: ${e.message}` }; }
586	    // A go carries every held reason, joined as the engine's verdict joins them;
587	    // a decline or an error is the precondition's own, untouched.
588	    if (verdict.error || verdict.run === false) return verdict;
589	    return { ...verdict, run: true, reason: [history.reason, verdict.reason].filter(Boolean).join('; ') };
590	  }
591	
592	  // F18/F24: the episode boundary is an ARTIFACT on the item, not a property of
593	  // the label transition. Modelling it as "every transition into ready opens a
594	  // new episode" is what made this simulator unable to reproduce F24: it encoded
595	  // the rule's intent, so the paths that end an episode without writing anything
596	  // looked correct here and livelocked in production. So the epoch advances
597	  // exactly where the engine leaves a mark — the scheduler run's reclaim, the F15 revert,
598	  // and the departing executor's strike on a roll or a park (PRINCIPLES.md).
599	  //
600	  // A human re-queue deliberately does NOT advance it: a human editing labels
601	  // writes no comment, which is precisely why the strike has to have happened
602	  // already.
603	  function endEpisode(it) { it.claimEpoch = seq++; }
604	
605	  // `dispatchDrain: false` is for closes whose caller already has a drain
606	  // coming — the executor's own loop picks the next item in the same run, and
607	  // the scheduler run's dedupe close is followed by that run's drain job —
608	  // so only a close with no run behind it (an agent session's) dispatches one.
609	  // What still makes something newly pickable after such a close is the
610	  // `schedule_after` yield resolving — never a Blocked-by dependent, which
611	  // a close no longer touches at all (docs/PRINCIPLES.md; #1373 reversed an earlier attempt): that
612	  // release is the scheduler run's readiness job alone, on its own hourly pass.
613	  function close(it, outcome, { dispatchDrain = true } = {}) {
614	    it.state = 'closed';
615	    it.closedAt = now;
616	    it.outcome = outcome;
617	    // ONE ISSUE, ONE STATE. A marked issue IS its item, so a terminal that closes
618	    // the item closes the issue it stands on — `done` and `rejected` alike (PRINCIPLES.md).
619	    const req = it.request != null ? requestOf(it.request) : null;
620	    if (req && req.state === 'open') req.state = 'closed';
621	    // the terminal status goes ON; urgency ends with the item; the ORIGIN stays
622	    // for life — the closed issue keeps saying where it came from
623	    clearStatus(it);
624	    it.labels.delete('task:urgent');
625	    it.labels.add(outcome === 'done' ? 'task:status:done' : 'task:status:rejected');
626	    record('close', { task: it.taskId, issue: it.number, outcome });
627	    if (dispatchDrain && pickable().length > 0) {
628	      schedule(now + 1 * MIN, () => executorRun('E1', 'close-drain'));
629	    }
630	  }
631	
632	  // The scheduler run's own close of an item nobody picked (the F16 dedupe;
633	  // scheduler-run.mjs's `dedupe`/`retire-orphan`/`superseded` ops): it ADDS the
634	  // terminal label and closes, and the status the item waited in stays on — which
635	  // is exactly what the run history reads to know the item never ran (F32).
636	  function closeUnpicked(it) {
637	    it.state = 'closed';
638	    it.closedAt = now;
639	    it.outcome = 'rejected';
640	    it.labels.add('task:status:rejected');
641	    record('close', { task: it.taskId, issue: it.number, outcome: 'rejected' });
642	  }
643	
644	  // ---- the scheduler run (docs/PRINCIPLES.md): a stateless loop --------------
645	  function schedulerRun() {
646	    if (suspendedAll) { record('suspended-skip', { workflow: 'scheduler-run' }); return; }
647	    record('scheduler-run', {});
648	    // job 1: ASK every task on the schedule, at every tick. A yes files a READY
649	    // item; a no is the `ask` log entry and nothing else — no board, no
650	    // watermark, nothing durable can eat a run, and the next tick asks again; a
651	    // read the scheduler cannot make fails OPEN and the executor decides at pick.
652	    for (const task of registry.values()) {
653	      // A task off the schedule — stating no condition, or one that reads the
654	      // item itself — runs only from an item somebody created (docs/PRINCIPLES.md):
655	      // the schedule never asks it.
656	      if (!isScheduled(task)) continue;
657	      // ONE LIVE ITEM PER TASK, the engine's one invariant: an open item that is
658	      // blocked, waiting or running is the task's current occurrence, and the
659	      // task is not asked while it stands. A PARKED item is not live — it is a
660	      // person's inbox or a fault on record — and whether it holds the task is
661	      // the task's own declaration (`last-run-not-failed`), never the engine's:
662	      // absent that term the next occurrence is filed beside the park, which the
663	      // dedupe below must never mistake for a duplicate.
664	      const live = family(task.id).filter((i) => i.state === 'open' && isLive(i))
665	        .sort((a, b) => a.number - b.number);
666	      // F16 self-heal, FIRST: if a stale issue list ever let a duplicate
667	      // standing item through (nothing guarantees a REST list from another node
668	      // sees a creation seconds old), close every live one but the oldest. The
669	      // scheduler run is serialized (concurrency group), so this cannot race itself.
670	      for (const dup of live.slice(1)) {
671	        closeUnpicked(dup);
672	        record('dedupe', { task: task.id, issue: dup.number });
673	      }
674	      if (live.length > 0) continue; // the standing item already exists
675	      const { verdict, reason } = askAtTick(task);
676	      record('ask', { task: task.id, verdict, reason });
677	      if (verdict === 'no') continue; // no work, no item, nothing written
678	      if (failNextCreateOf.delete(task.id)) {
679	        record('create-failed', { task: task.id });
680	        continue; // the POST was refused; nothing exists, and the next tick asks again
681	      }
682	      createIssue({ taskId: task.id, labels: ['task:status:waiting-for-executor'] });
683	    }
684	    // job 2: ready whatever is due
685	    for (const it of open().filter((i) => is(i, 'task:status:blocked'))) {
686	      const blockersDone = it.blockedBy.every(
687	        (n) => issues.find((x) => x.number === n)?.state === 'closed'
688	      );
689	      if (blockersDone && (it.notBefore === null || now >= it.notBefore)) {
690	        setStatus(it, 'task:status:waiting-for-executor');
691	        record('ready', { task: it.taskId, issue: it.number });
692	      }
693	    }
694	    // ---- job 4: adopt the marked issues (PRINCIPLES.md, one-issue) ----------
695	    // Label mechanics like the other three: no precondition, no signal, no
696	    // judgment about WHO marked it (that is the precondition's, at pickup).
697	    // The marked issue IS the work item. The exactly-once guard is the mark
698	    // with NO status: adoption writes the first status, and any status — live,
699	    // parked or terminal — blocks re-adoption until a person clears it, which
700	    // makes clearing the status the ONE re-ask lever (docs/PRINCIPLES.md) — the
701	    // old re-queue and re-mark levers used to be two; the one-issue shape collapses them.
702	    for (const req of requests.filter((r) => r.state === 'open'
703	        && r.labels.has(ORIGIN_AD_HOC) && statusOf(r) === null)) {
704	      const prior = issues.find((i) => i.request === req.number);
705	      if (prior) {
706	        // the same record re-enters the queue — a cleared park or a cleared
707	        // terminal is a re-ask, and the engine's write marks the episode. The
708	        // model is re-gated from the body as it stands NOW: each ask names its
709	        // model afresh, and nothing stale outranks it (F29's guarantee, kept
710	        // without any label to consume).
711	        prior.model = gatedModel(req, permissionOf);
712	        prior.state = 'open'; prior.closedAt = null; prior.outcome = null;
713	        setStatus(prior, READY);
714	        endEpisode(prior);
715	        record('adopt', { task: REQUEST_TASK, issue: prior.number, request: req.number, model: prior.model, readopt: true });
716	        continue;
717	      }
718	      // The machine block, appended at adoption: the task path and the gated
719	      // parameters. The model is honored only when the AUTHOR holds push
720	      // access (PRINCIPLES.md) — the body is author-editable where a label was
721	      // write-gated, so an ungated ask still runs, at the default.
722	      const model = gatedModel(req, permissionOf);
723	      const it = {
724	        request: req.number, model,
725	        number: req.number, title: `request #${req.number}`, taskId: REQUEST_TASK, qualifier: null,
726	        labels: req.labels, // ONE issue: the item's labels ARE the issue's
727	        state: 'open', createdAt: now, closedAt: null,
728	        readySince: now, lastActivity: now,
729	        notBefore: null, blockedBy: [], woken: null,
730	        outcome: null, comments: [], escalated: false,
731	        sessions: [], quarantined: false,
732	      };
733	      issues.push(it);
734	      setStatus(it, READY);
735	      record('adopt', { task: REQUEST_TASK, issue: it.number, request: req.number, model });
736	    }
737	    for (const it of open().filter((i) => is(i, 'task:status:running-executor'))) {
738	      if (now - it.lastActivity >= executingLeashMs) {
739	        setStatus(it, 'task:status:waiting-for-executor');
740	        it.comments.push({ t: now, body: 'reclaimed: executor went silent past the leash' });
741	        endEpisode(it);
742	        record('reclaim', { task: it.taskId, issue: it.number });
743	      }
744	    }
745	    // The drain job (#1212): dispatched only when the scheduler run's parting
746	    // look at the queue found something pickable — the job output the real
747	    // drain job gates on. An idle hour costs the cron's one run, not two;
748	    // the guaranteed delivery is unchanged, because anything an event failed
749	    // to deliver is exactly what this look sees.
750	    if (pickable().length > 0) schedule(now + 40_000, () => executorRun('E1', 'scheduler-run-drain'));
751	    else record('drain-skipped', {});
752	  }
753	
754	  // The two write-backs onto the request issue (PRINCIPLES.md). Whoever converges
755	  // the item owns the write-back for the end it converged: the executor for a
756	  // declined request, the session for a run that left a PR. A run that FAILED
757	  // writes nothing and leaves the queued label standing — re-arming work that
758	  // writes code is a person's decision, and that standing label is also what stops
759	  // the scheduler run adopting the same request a second time.
760	  // A refused request DISARMS on the issue itself (PRINCIPLES.md): the terminal status
761	  // lands on the issue and closes it, and blocks re-adoption until a person clears
762	  // it (the re-ask lever). The one comment says why. There is no separate
763	  // in-review write-back: the approval park IS the in-review state, on the same
764	  // labels.
765	  function declineRequest(it, why) {
766	    const req = requestOf(it.request);
767	    if (!req) return;
768	    req.comments.push({ login: 'claudinite', body: `declined: ${why}` });
769	    record('request-declined', { issue: req.number, why });
770	  }
771	
772	  // ---- the executor (PRINCIPLES.md) ---------------------------------------------
773	  function pickable() {
774	    const ready = open().filter((i) => is(i, 'task:status:waiting-for-executor'));
775	    const live = (taskId) => {
776	      const s = standingItem(taskId);
777	      return s && ['task:status:waiting-for-executor', 'task:status:running-executor', 'task:status:running-agent'].some((l) => has(s, l));
778	    };
779	    return ready
780	      .filter((i) => !i.quarantined) // an item no live executor can reach (S18)
781	      .filter((i) => {
782	        // same-title mutex: one task, one execution at a time
783	        if (open().some((o) => o !== i && o.title === i.title &&
784	              (is(o, 'task:status:running-executor') || is(o, 'task:status:running-agent')))) return false;
785	        // the `schedule_after` yield: skip while the upstream's standing item is live
786	        // this cycle (a declined or needs-human upstream does not block — S23)
787	        if (isStanding(i)) {
788	          const ups = registry.get(i.taskId)?.schedule_after ?? [];
789	          if (ups.some((up) => live(up))) return false;
790	        }
791	        return true;
792	      })
793	      .map((i) => ({ i, r: prng() }))
794	      // urgent first, then RANDOM among the ready (owner, 2026-08-15) — two
795	      // executors listing the same queue then contend on DIFFERENT heads, and
796	      // nothing leaned on oldest-first: the stale-ready escalation is
797	      // period-scale, indifferent to minute-scale pick reordering
798	      .sort((a, b) =>
799	        (has(b.i, 'task:urgent') ? 1 : 0) - (has(a.i, 'task:urgent') ? 1 : 0) ||
800	        a.r - b.r)
801	      .map(({ i }) => i);
802	  }
803	
804	  // The claim is the verified lease (PRINCIPLES.md): swap, post a claim
805	  // comment, re-read — earliest comment wins, the loser reverts nothing and
806	  // moves on. `preRead` is the label state the executor saw when it read the
807	  // item; a racing executor's stale read is modeled by passing the snapshot
808	  // taken before the rival's swap landed.
809	  function claim(it, execId, preRead) {
810	    if (statusOf({ labels: preRead }) !== READY) return false;
811	    setStatus(it, 'task:status:running-executor');
812	    it.readySince = null;
813	    it.lastActivity = now;
814	    it.comments.push({ t: now, seq: seq++, kind: 'claim', exec: execId });
815	    // F18: arbitrate only among THIS episode's claims — earliest since the
816	    // item last became ready, by server-assigned comment order
817	    const claims = it.comments.filter((c) => c.kind === 'claim' && c.seq > (it.claimEpoch ?? -1));
818	    const won = claims[0].exec === execId;
819	    record(won ? 'claim' : 'claim-lost', { task: it.taskId, issue: it.number, exec: execId });
820	    return won; // loser reverts nothing — the winner's labels already stand
821	  }
822	
823	  // Hand-off + invocation (PRINCIPLES.md, as amended 2026-08-15): swap to
824	  // task:status:running-agent, then fire the endpoint EXACTLY ONCE — never retried, because a
825	  // retry is only safe when the first call is known to have done nothing, and
826	  // the unanswered case is exactly where nothing can be known. Three outcomes:
827	  //  - fired      → a session exists; the item is the agent's
828	  //  - refused    → a status came back, no session exists and none will (a
829	  //                 token / URL / routine is wrong, which no retry fixes):
830	  //                 converge needs-human naming the cause
831	  //  - unanswered → the session may or may not exist and nothing may guess:
832	  //                 the item STAYS task:status:running-agent with the outcome-unknown comment;
833	  //                 a session that started converges it, one that never did
834	  //                 leaves it silent until the janitor's agent leash (PRINCIPLES.md)
