836	  // sessions can never arrive at one item, so there is nothing to arbitrate.
837	  function handOff(it, task) {
838	    setStatus(it, 'task:status:running-agent');
839	    if (world._apiRefusedUntil != null && now < world._apiRefusedUntil) {
840	      record('handoff-refused', { task: it.taskId, issue: it.number });
841	      park(it, 'task:status:running-agent', 'action'); // a token, a URL or a routine is wrong
842	      return;
843	    }
844	    if (world._apiUnanswered) {
845	      const { started } = world._apiUnanswered;
846	      world._apiUnanswered = null;
847	      record('handoff-unanswered', { task: it.taskId, issue: it.number, started });
848	      it.comments.push({ t: now, body: 'invocation got no answer — outcome unknown, the agent leash decides' });
849	      if (!started) return; // silent item; the janitor's agent leash is the recovery
850	      const s = { id: `s-${++sessionSeq}`, item: it.number };
851	      it.sessions.push(s);
852	      schedule(now + 30_000, () => startAgentSession(s, it, task));
853	      return;
854	    }
855	    record('handoff', { task: it.taskId, issue: it.number });
856	    const s = { id: `s-${++sessionSeq}`, item: it.number };
857	    it.sessions.push(s);
858	    schedule(now + 30_000, () => startAgentSession(s, it, task));
859	  }
860	
861	  function startAgentSession(s, it, task) {
862	    if (it.state !== 'open' || !is(it, 'task:status:running-agent')) return;
863	    // No agent-side claim (PRINCIPLES.md, amended 2026-08-15): the session checks,
864	    // not claims — the item wears task:status:running-agent and the fire's nonce matches the
865	    // newest hand-off, both modeled by the guard above.
866	    it.lastActivity = now;
867	    if (crashAgentOf.delete(it.taskId)) {
868	      record('agent-died', { task: it.taskId, issue: it.number, session: s.id });
869	      return; // never converges; the janitor's agent leash is the recovery (S11)
870	    }
871	    schedule(now + task.agentMinutes * MIN, () => {
872	      if (it.state !== 'open') return;
873	      if (task.agentFails?.(world, now)) {
874	        park(it, 'task:status:running-agent', 'failure');
875	        record('agent-failed', { task: it.taskId, issue: it.number });
876	        return;
877	      }
878	      // The agentic mirror of the code-work approval park below: a SESSION that
879	      // deliberately left an unmerged PR is in the same position as a worker that
880	      // did — succeeded, not finished, waiting on a named reviewer. Modeled here
881	      // because the request task is the first agentic task whose every successful
882	      // run ends that way.
883	      if (task.deliversOpenPr?.(world, now)) {
884	        park(it, 'task:status:running-agent', 'approval');
885	        record('delivered-open-pr', { task: it.taskId, issue: it.number });
886	        return;
887	      }
888	      close(it, task.outcome ?? 'done');
889	    });
890	  }
891	
892	  // One claimed item through to its settle. `onSettled` is the RUN's
893	  // continuation — called when the item stops occupying this executor (close,
894	  // hand-off, work failure), and deliberately NOT called when the
895	  // runner itself dies (the run died with it; the leash is the recovery).
896	  // The hand-off settles the item for the run: the executor never waits for
897	  // the agent, which is why agent work parallelizes and executor work is the
898	  // occupancy (PRINCIPLES.md).
899	  function executeClaimed(it, task, onSettled = () => {}) {
900	    if (crashNextOf.delete(it.taskId)) {
901	      record('executor-crash', { task: it.taskId, issue: it.number });
902	      // The workflow's failure-continuation job (needs: execute, if:
903	      // failure() || cancelled()) re-dispatches on a fresh runner, so a dead
904	      // run never stalls the train — the crashed ITEM still waits for the
905	      // leash reclaim; only the QUEUE keeps moving (S36).
906	      schedule(now + 1 * MIN, () => executorRun('E-failover', 'failure-redispatch'));
907	      return; // died mid-claim: labels stay, the leash reclaim recovers (S8)
908	    }
909	    // the pick-time precondition evaluation (PRINCIPLES.md) — the executor
910	    // re-derives the verdict even where the scheduler run already asked at the
911	    // tick: nothing is carried forward from the tick's answer. Over the item's
912	    // own facts and its own run history (excluding it), so a woken item passes
913	    // the cadence terms and a request item's verdict is about the issue it names.
914	    const verdict = askAtPick(task, it);
915	    // A precondition that CANNOT ANSWER is a run failure, not a verdict (F27):
916	    // the item parks in the failure lane, open and visible, and the re-queue
917	    // lever retries it — where a decline would converge on a guess.
918	    if (verdict.error) {
919	      record('evaluate-failed', { task: it.taskId, issue: it.number, why: verdict.error });
920	      endEpisode(it);                           // F24: a park strikes its claim
921	      park(it, 'task:status:running-executor', 'failure');
922	      onSettled();
923	      return;
924	    }
925	    record('evaluate', { task: it.taskId, issue: it.number, run: verdict.run !== false, reason: verdict.reason ?? null });
926	    if (verdict.run === false) {
927	      // A decline CLOSES the item with the reason — standing and ad-hoc alike.
928	      // For a standing item the next occurrence is the scheduler run's ask at
929	      // the next tick, where the `due:` term's closed-at half keeps this period
930	      // consumed; "asked and declined" lives nowhere but this record.
931	      // A declined request tells the ISSUE so and disarms it, in the same
932	      // convergence: nothing else would, and an un-disarmed issue would be
933	      // re-adopted and re-refused on every scheduler run forever. The terminal
934	      // closes it, marked or filed — a rejected run is not a question anybody has
935	      // left to answer (PRINCIPLES.md).
936	      if (it.request != null) {
937	        declineRequest(it, verdict.reason ?? 'the precondition declined');
938	        endEpisode(it);
939	      }
940	      close(it, 'rejected', { dispatchDrain: false });
941	      record('decline-close', { task: it.taskId, issue: it.number, reason: verdict.reason ?? 'no work' });
942	      onSettled();
943	      return;
944	    }
945	    // the work step → optional hand-off → converge, as timed phases. The
946	    // executor re-verifies its OWN lease at the transition (F17): not just "is
947	    // the item executing" but "is my claim still the newest" — a reclaim-then-
948	    // re-pick puts a newer claim on the item, and the stale runner must see
949	    // it and abandon silently rather than hand off work it no longer owns.
950	    const myClaim = it.comments.filter((c) => c.kind === 'claim').at(-1);
951	    const mineStill = () => it.state === 'open' && is(it, 'task:status:running-executor') &&
952	      it.comments.filter((c) => c.kind === 'claim').at(-1) === myClaim;
953	    const workMs = (task.codeWorkMinutes ?? 1) * MIN;
954	    const diesAtMin = crashDuringWorkOf.has(it.taskId)
955	      ? crashDuringWorkOf.get(it.taskId) : null;
956	    if (diesAtMin !== null) crashDuringWorkOf.delete(it.taskId);
957	    // Heartbeat comments during the work step (work-as-work review,
958	    // 2026-08-15): the executor touches the item every heartbeatMinutes, so
959	    // the leash reclaims a DEAD executor within ~leash regardless of how long
960	    // the work legally runs — and the item's timeline shows live progress
961	    // instead of going dark for the duration.
962	    if (!heartbeatsDisabled) {
963	      for (let m = heartbeatMinutes; m * MIN < workMs; m += heartbeatMinutes) {
964	        if (diesAtMin !== null && m >= diesAtMin) break;
965	        schedule(now + m * MIN, () => {
966	          if (!mineStill()) return;
967	          it.lastActivity = now;
968	          record('heartbeat', { task: it.taskId, issue: it.number });
969	        });
970	      }
971	    }
972	    if (diesAtMin !== null) {
973	      // the runner dies mid-work: heartbeats stop, the completion never runs,
974	      // and the leash reclaims from the LAST heartbeat — recovery is bounded
975	      // by the leash, not by the work's duration
976	      schedule(now + diesAtMin * MIN, () => {
