1352	      const it = {
1353	        number: issues.length + 700, title, taskId: null, qualifier: null,
1354	        labels: new Set(['agent-dispatch']), state: 'open',
1355	        createdAt: now, closedAt: null, readySince: null, lastActivity: now,
1356	        notBefore: null, blockedBy: [], woken: null, outcome: null, comments: [],
1357	        escalated: false, sessions: [],
1358	        quarantined: false,
1359	      };
1360	      issues.push(it);
1361	      return it;
1362	    },
1363	
1364	    // ---- multi-executor contention (S7) ------------------------------------
1365	    // Two executors read the SAME snapshot of the ready list, so both pick
1366	    // the same first item; both swap and post claim comments; the earliest
1367	    // comment wins and the loser moves on to the next item read from LIVE
1368	    // state — the verified lease, stale-read and all (PRINCIPLES.md).
1369	    // spread: false (default) — both executors pick the SAME first item (S7's
1370	    // one-item race). spread: true — executor i picks snapshot[i]: different
1371	    // items, claimed simultaneously from the same stale read, which is how a
1372	    // twin pair or an upstream+dependent slip past the pick filters together
1373	    // (S32/F15) — only the post-claim re-verify serializes them.
1374	    raceExecutorsAt(isoTime, execIds, { spread = false } = {}) {
1375	      schedule(T(isoTime), () => {
1376	        const snapshot = pickable();
1377	        const preReads = new Map(snapshot.map((i) => [i, new Set(i.labels)]));
1378	        const winners = [];
1379	        execIds.forEach((execId, k) => {
1380	          const target = spread ? snapshot[k] : snapshot[0];
1381	          if (!target) return;
1382	          if (claim(target, execId, preReads.get(target))) winners.push([target, execId]);
1383	          else executorRun(execId); // same-item loser moves on, from live state
1384	        });
1385	        for (const [target, execId] of winners) {
1386	          if (!postClaimVerify(target, execId)) continue;
1387	          const task = registry.get(target.taskId);
1388	          if (task) executeClaimed(target, task);
1389	        }
1390	      });
1391	      return sim;
1392	    },
1393	
1394	    // F16's precondition: a scheduler run whose issue list was stale created a second
1395	    // standing item. Injected directly — the sim's own scheduler run can't produce it.
1396	    injectDuplicateStanding(taskId) {
1397	      return createIssue({ taskId, labels: ['task:status:waiting-for-executor'] });
1398	    },
1399	
1400	    // ---- the scheduler's fail-open levers ----------------------------------
1401	    // The scheduler run cannot collect this task's signals (a missing
1402	    // credential): its ask fails OPEN — the item is created and the executor,
1403	    // which holds the credentials, decides at pick. Only on ticks where the
1404	    // run-history terms did not already decline: those need no signal.
1405	    setSignalsUnavailable(taskId, on = true) {
1406	      if (on) signalsUnavailable.add(taskId); else signalsUnavailable.delete(taskId);
1407	      return sim;
1408	    },
1409	    // The next work-item POST for this task is refused (F31's write failure).
1410	    failNextCreateOf(taskId) { failNextCreateOf.add(taskId); return sim; },
1411	
1412	    // ---- platform failure injection (S9/S10) -------------------------------
1413	    // refused: the endpoint answers with an error status — no session exists
1414	    apiRefusedUntil(isoTime) { world._apiRefusedUntil = T(isoTime); return sim; },
1415	    // unanswered: timeout/dropped connection — `started` says whether the call
1416	    // actually created a session on the far side (the executor cannot know)
1417	    apiUnansweredOnce({ started }) { world._apiUnanswered = { started }; return sim; },
1418	
1419	    // ---- fleet / human levers ----------------------------------------------
1420	    quarantine(number) { issues.find((i) => i.number === number).quarantined = true; return sim; },
1421	    closeByHand(number, outcome = 'rejected') {
1422	      const it = issues.find((i) => i.number === number);
1423	      it.state = 'closed'; it.closedAt = now; it.outcome = outcome;
1424	      for (const l of [...it.labels]) if (l.startsWith('task:') || l === 'needs-human') it.labels.delete(l);
1425	      record('close', { task: it.taskId, issue: it.number, outcome, by: 'hand' });
1426	      return sim;
1427	    },
1428	    // the operator hold (PRINCIPLES.md): set/clear the suspend-all variable. Resume
1429	    // needs no dispatch of its own — the next cron scheduler run self-heals — but the
1430	    // impatient path is a hand-dispatched scheduler run (schedulerRunAt models it).
1431	    suspendAll() { suspendedAll = true; record('suspend', {}); return sim; },
1432	    resumeAll() { suspendedAll = false; record('resume', {}); return sim; },
