1	// The scheduler run (docs/PRINCIPLES.md) — the whole of the queue's
2	// scheduled machinery, and a stateless loop: at every tick it asks every declared
3	// task, through the task's own preconditions, whether it wants to run now, and
4	// files an issue only on a yes (docs/PRINCIPLES.md).
5	//
6	// Four jobs: ASK — every task on the schedule, through the injectable `evaluate`
7	// seam; a yes creates the work item, a no is a log line, and a read the scheduler
8	// cannot make fails OPEN and creates the item for the executor to decide; READY
9	// blocked items whose dependencies have resolved and whose not-before has passed;
10	// ADOPT the issues somebody marked for implementation; and RECLAIM dead executor
11	// claims. The executor still re-evaluates at pick (PRINCIPLES.md). The engine keeps no
12	// memory of an ask: a task's cadence is a condition over its own run history,
13	// read off the queue, so a decline is simply asked again at the next tick and
14	// nothing durable can eat a run. One invariant is the engine's own — ONE LIVE ITEM
15	// PER TASK: while a task's item is blocked, waiting or running, it is not asked.
16	// Beside job 1, the reap of a standing item whose task is no longer declared at
17	// HEAD.
18	//
19	// The run's last act is the DRAIN GATE (PRINCIPLES.md): it reports whether it left
20	// anything pickable, and the workflow's drain job starts an executor only then —
21	// an idle tick costs this one run rather than two.
22	//
23	// `planSchedulerRun` is the decision core, kept injectable so it tests with fixtures; the
24	// CLI shell below wires the GitHub reads, the signal-collection seam, and applies the ops.
25	
26	import { pathToFileURL } from 'node:url';
27	import { isSuspended, suspendedNotice } from '../world/hold.mjs';
28	import { EXECUTING_LEASH_MS } from '../items/leases.mjs';
29	import { swapStatus } from '../items/apply-status.mjs';
30	import { isReleasable } from './readiness.mjs';
31	import { isQueueItem } from '../items/read.mjs';
32	import { pickOrder } from '../items/pick-order.mjs';
33	import { lastLivenessAt } from '../items/heartbeat.mjs';
34	import {
35	  WORK_PREFIX, BLOCKED, READY, TASK_OBSOLETE,
36	  NEEDS_HUMAN_DECISION, LIVE_STATUSES,
37	  STATUS_BLOCKED, STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT,
38	  isStatus, statusOf,
39	  QUEUE_LABELS, EPISODE_MARKER, workItemTitle, parseWorkItemTitle, parseWorkItemBody, taskIdFromPath,
40	  workItemBody, labelNames, hasLabel,
41	  ORIGIN_AD_HOC, ORIGIN_PLANNED, ORIGIN_LABELS, REQUEST_LABEL, parseRequestFields,
42	  parseBlockedBy, withMachineBlock,
43	} from '../items/work-item.mjs';
44	import { REQUEST_TASK_ID } from '../contract/built-in-tasks.mjs';
45	import { taskSignalNames, isScheduledTask } from '../contract/task-contract.mjs';
46	import { evaluatePreconditions } from '../contract/precondition-policy.mjs';
47	import { RUN_HORIZON_DAYS } from '../signals/index.mjs';
48	import { actionsEnv, repoRoot, setStepOutput } from '../world/actions.mjs';
49	import { now as clockNow } from '../world/clock.mjs';
50	import { listIssuesByQuery, collaboratorPermission, getIssue, setIssueBody } from '../world/github.mjs';
51	
52	// The scheduler run owns the executing-leash reclaim because it is deterministic and
53	// hourly, which recovers a dead executor's item in ~2h rather than the janitor's
54	// ~25h (PRINCIPLES.md, owner decision 6).
55	export { EXECUTING_LEASH_MS };
56	
57	const ms = (t) => (t == null ? null : new Date(t).getTime());
58	
59	// The ops `planSchedulerRun` emits, each a label-and-body mechanic the shell applies:
60	//   { kind: 'dedupe',  issue, reason }            close, task:obsolete
61	//   { kind: 'create',  pack, task, labels, body } a task's standing item
62	//   { kind: 'ready',   issue }                    task:blocked -> task:ready
63	//   { kind: 'reclaim', issue, reason }            task:executing -> task:ready
64	//   { kind: 'adopt',   request, title, body, … }  a marked issue becomes an item
65	//   { kind: 'supersede', issue, request, reason } a parked prior run of a re-ask
66	//   { kind: 'retire-orphan', issue, reason }      a standing item whose task is gone closes
67	//
68	// Beside the ops, `asked`: one `{ task, verdict, reason }` per task this run asked,
69	// `verdict` being `go`, `no` or `fail-open` — the run's log, and the whole record
70	// of a decline, since nothing durable is written for one.
71	//
72	// `items` is every `[claudinite-work]` issue the shell fetched (state=all back to
73	// the run-history horizon, open for the rest), each `{ number, title, body, state,
74	// labels, created_at, closed_at, updated_at }`. `stateOf(number)` answers the
75	// state of a `Blocked-by` target that may not be a work item at all; an unknown
76	// number is never treated as closed, so an unreadable blocker delays rather than
77	// releases (the convergence-not-prevention posture).
78	//
79	// `evaluate(task)` is the ask: async, returning the precondition's verdict `{
80	// run, reason, … }` or `{ error }` where the scheduler could not decide — a
81	// missing credential, a failed signal read, a throwing term. An error FAILS OPEN:
82	// the item is created and the executor, which holds the credentials, decides at
83	// pick. It is REQUIRED wherever a task is asked — a fixture with no seam and a
84	// task to ask is a fixture that has not said what the task answers.
85	export async function planSchedulerRun({
86	  tasks, items = [], requests = [], now, schedule, executingLeashMs = EXECUTING_LEASH_MS,
87	  stateOf = () => null, evaluate = null,
88	}) {
89	  const nowMs = ms(now);
90	  const ops = [];
91	  const asked = [];
92	  // REPO SHAPE IS NOT A PRECONDITION (docs/PRINCIPLES.md). "This repo ships the store pipeline", "this repo is a canon
93	  // home with a fleet token" are facts adoption settled, not questions worth
94	  // re-asking every tick — so a repo that carries a pack but not one task's
95	  // subject names that task in `taskScheduler.disabledTasks` and it is never
96	  // asked. Read here rather than at pick, because the cheapest run is the one
97	  // that files no item at all.
98	  const disabled = new Set(schedule?.disabledTasks ?? []);
99	  const closedByThisRun = new Set();
100	
101	  // ---- the orphan reap ----------------------------------------------------
102	  // A blocked standing item whose `<pack>/<task>` is not declared at HEAD can
103	  // never execute — job 1 matches its family title-exact on the declared id, so a
104	  // legacy pack spelling is invisible to it, and job 2 would otherwise ready the
105	  // item at its Not-before and hand an executor a task path that is not on disk.
106	  // Guarded on a non-empty task list so an unreadable declaration reaps nothing,
107	  // and scoped to BLOCKED so nothing in flight is touched — a ready orphan is
108	  // picked within the tick and parks for a human, which is visible rather than
109	  // silent. Items waiting on a blocker are untouched: they are somebody's
110	  // dependency, not a schedule's.
111	  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
112	  for (const item of items) {
113	    if (item.state !== 'open' || !isStatus(item, STATUS_BLOCKED) || !tasks.length) continue;
114	    const parsed = parseWorkItemTitle(item.title);
115	    if (!parsed || parsed.qualifier !== null) continue;
116	    const key = `${parsed.pack}/${parsed.task}`;
117	    if (parseWorkItemBody(item.body).blockedBy.length) continue;
118	    if (byId.has(key) && !disabled.has(key)) continue;
119	    closedByThisRun.add(item.number);
120	    ops.push({
121	      kind: 'retire-orphan', issue: item.number, pack: parsed.pack, task: parsed.task,
122	      reason: disabled.has(key)
123	        ? `Closing: \`${key}\` is named in this repository's \`taskScheduler.disabledTasks\`, so it is not `
124	          + 'asked here. Remove it from that list to bring the task back.'
125	        : `Closing: \`${key}\` is no longer declared on this repository, so this item names a task `
126	          + 'that is not at HEAD and can never run. If the task came back under a new id, its own item is the live one.',
127	    });
128	  }
129	
130	  // ---- job 1: ask every task on the schedule; a yes files the item ----------
131	  const live = (i) => LIVE_STATUSES.some((s) => isStatus(i, s));
132	  for (const task of tasks) {
133	    // A task whose declaration says `trigger: 'request'` runs only from an item
134	    // somebody created (docs/PRINCIPLES.md): the schedule never asks it, and its items
135	    // keep their own titles.
136	    if (!isScheduledTask(task.decl)) continue;
137	    const key = `${task.pack}/${task.id}`;
138	    if (disabled.has(key)) continue;
139	    const title = workItemTitle({ pack: task.pack, task: task.id });
140	    // The family is title-EXACT, which is also what makes it STRUCTURALLY the
141	    // standing family (PRINCIPLES.md): this task is on the schedule and the title carries
142	    // no qualifier, so a fan-out target or a request — qualified, both of them — is
143	    // a different title and neither suppresses nor consumes an occurrence (PRINCIPLES.md).
144	    const family = items.filter((i) => (i.title ?? '').trim() === title);
145	    // ONE LIVE ITEM PER TASK, the engine's one invariant: an open item that is
146	    // blocked, waiting or running is the task's current occurrence, and the task is
147	    // not asked while it stands. A PARKED item is not live — it is a person's inbox
148	    // or a fault on record — and whether it holds the task is the task's own
149	    // declaration (`last-run-not-failed`), never the engine's: absent that term the
150	    // next occurrence is filed beside the park, which the dedupe below must never
151	    // mistake for a duplicate.
152	    const open = family
153	      .filter((i) => i.state === 'open' && !closedByThisRun.has(i.number) && live(i))
154	      .sort((a, b) => a.number - b.number);
155	
156	    // F16 self-heal, FIRST: nothing documents that a REST list from another node
157	    // sees a creation seconds old, so a stale list can let a duplicate standing
158	    // item through. Assume it will happen rather than that it won't — close every
159	    // live family item but the oldest. Serialized by the scheduler run's concurrency
160	    // group, so this can never race itself.
161	    for (const dup of open.slice(1)) {
162	      closedByThisRun.add(dup.number);
163	      ops.push({
164	        kind: 'dedupe', issue: dup.number, pack: task.pack, task: task.id,
165	        reason: `a duplicate standing item for ${task.pack}/${task.id} — #${open[0].number} is this task's standing item`,
166	      });
167	    }
168	    if (open.length) continue; // the standing item already exists
169	
170	    if (!evaluate) throw new Error(`planSchedulerRun has a task to ask (${key}) and no evaluate seam to ask it through`);
171	    const verdict = (await evaluate(task)) ?? {};
172	    if (verdict.error) {
173	      // Fail open: never fewer runs because a read failed — the executor, which
174	      // holds the credentials, decides at pick (PRINCIPLES.md).
175	      asked.push({ task: key, verdict: 'fail-open', reason: verdict.error });
176	    } else if (verdict.run !== true) {
177	      // No work, no item, nothing written: the next tick asks again.
178	      asked.push({ task: key, verdict: 'no', reason: verdict.reason || 'no work' });
179	      continue;
180	    } else {
181	      asked.push({ task: key, verdict: 'go', reason: verdict.reason || '' });
182	    }
183	    ops.push({
184	      kind: 'create', pack: task.pack, task: task.id, title,
185	      // THE ORIGIN, worn for the item's whole life beside whatever status it holds
186	      // (PRINCIPLES.md): the schedule filed this one, so it is `planned`.
187	      labels: [ORIGIN_PLANNED, READY],
188	      body: workItemBody({
189	        taskPath: task.taskPath,
190	        context: verdict.error ? [`The scheduler could not decide this occurrence (${verdict.error}); the executor decides at pick.`] : [],
191	      }),
192	      notBefore: null,
193	    });
194	  }
195	
196	  // ---- job 2: ready whatever is due (any origin) --------------------------
197	  // The only site that ever releases a blocked item (docs/PRINCIPLES.md; #1373
198	  // reversed an earlier attempt to release one at close instead): a converge
199	  // writes only to the item it holds, so nothing else asks this question.
200	  for (const item of items) {
201	    if (closedByThisRun.has(item.number)) continue;
202	    if (isReleasable(item, { stateOf, nowMs })) ops.push({ kind: 'ready', issue: item.number });
203	  }
204	
205	  // ---- job 4: adopt the issues somebody marked (docs/PRINCIPLES.md) ------
206	  // Label mechanics like the other three: no precondition, no signal, and no
207	  // judgment about WHETHER the marked issue may run — that verdict is the request
208	  // task's precondition, at pickup, where every verdict is.
209	  //
210	  // THE MARKED ISSUE IS THE ITEM. Adoption files nothing: it appends the machine
211	  // block to the issue's own body and applies the first status, and the whole
212	  // lifecycle then plays out where the person is already looking. `requests` is
213	  // every open issue wearing `task:origin:ad-hoc` with NO status — that combination
214	  // is the whole of the exactly-once guard, and any status at all (live, parked or
215	  // terminal) holds the mark until a person clears it. So there is no prior item to
216	  // wait on and none to supersede: an impatient re-ask mid-run is structurally
217	  // nothing, because there is no second label to apply.
218	  //
219	  // Adoption needs the task it targets to exist at HEAD; where it does not — an
220	  // engine older than the mode, or a `Task:` naming something this repo does not
221	  // carry — the mark simply waits, which is what every other "not yet capable"
222	  // state here does.
223	  const byTaskId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
224	  for (const req of requests) {
225	    const marked = hasLabel(req, ORIGIN_AD_HOC) || hasLabel(req, REQUEST_LABEL);
226	    if (req.state !== 'open' || !marked || statusOf(req) !== null) continue;
227	
228	    // The parameters ride the person's own text, re-read and re-gated at every
229	    // adoption (PRINCIPLES.md): the body is author-editable where a label was
230	    // platform-write-gated, so `Task:`, `Model:` and `Automerge:` are honoured only
231	    // for an author who holds push access. An ungated ask still runs — at the
232	    // default task and model, and authorized to land nothing.
233	    const asked = parseRequestFields(req.body, { gated: req.authorHasPush === true });
234	    const task = byTaskId.get(asked.task ?? REQUEST_TASK_ID) ?? null;
235	    if (!task) continue;
236	    // WHAT THE REQUEST WAITS ON (PRINCIPLES.md). A marked issue may name its blockers in
237	    // the same `Blocked-by:` field an item uses, which is how a follow-up filed
238	    // mid-session queues BEHIND the work in flight instead of racing it. A blocker
239	    // already closed holds nothing back — it is dropped here rather than carried and
240	    // immediately released. `Not-before:` rides the same rule, for the item's other
241	    // wait field: a deferred request waits on a moment as well as on an issue.
242	    const blockedBy = asked.blockedBy.filter((n) => stateOf(n) !== 'closed');
243	    const notBefore = asked.notBefore && ms(asked.notBefore) > nowMs ? asked.notBefore : null;
244	    ops.push({
245	      kind: 'adopt',
246	      request: req.number,
247	      task: `${task.pack}/${task.id}`,
248	      status: blockedBy.length || notBefore ? BLOCKED : READY,
249	      // The block is the machine's half of a body the human owns and keeps editing,
250	      // so it is written whole here and rewritten in place after that.
251	      body: withMachineBlock(req.body, workItemBody({
252	        taskPath: task.taskPath,
253	        request: req.number,
