311	// Which standing items a `wake` dispatch names. Forcing a scheduled task IS waking
312	// its standing item, and this is that same lever reached from OUTSIDE the repo: the
313	// fleet enforcer dispatches this workflow with the task ids it wants run now, and
314	// the member wakes its own items with its own token. The enforcer therefore needs
315	// no issue access anywhere — the fan-out model the enforcer's sweeps are built on, where
316	// the enforcer dispatches and the member executes.
317	//
318	// An id is `pack/task` or a bare `task` resolved against this repo's own discovered
319	// tasks, so a caller spanning many members never has to know any one member's pack
320	// layout. Every id that matches nothing comes back in `unmatched`: a force whose
321	// report counts only what it woke reads as coverage it did not have.
322	//
323	// An item already in flight (`task:ready`, `task:executing`, `task:agent`) is left
324	// alone and reported as `already`, never re-woken — an episode boundary dropped on
325	// a live claim is exactly the livelock F18 describes.
326	//
327	// WHEN THE STANDING ITEM DOES NOT EXIST, forcing MINTS it (PRINCIPLES.md's other lever). A
328	// task that completes closes its item, and the next one appears only when the
329	// task next says yes — so between the two there is nothing to wake, and that gap
330	// is the common case rather than an edge: a daily task is missing its item for
331	// most of the day. A force that reported "nothing to wake" there would fail on
332	// most members most of the time, which is precisely what a fleet-wide converge
333	// lever must not do. The minted item is an ordinary standing item — same title,
334	// no qualifier — stamped `Woken:` so the task's cadence terms hold on it (a
335	// person's wake stands in for the cadence) while everything else it requires
336	// still applies; it is the task's live item, so the scheduler asks nothing beside it.
337	//
338	// A WOKEN-GATED task is the exception, and never minted: it has no standing item
339	// to stand in for — an item exists only because an issue named the task (a
340	// verification's `Task:` line, a marked request), and a bare one carries nothing
341	// its worker can read, so it can only park (#1721). Its items keep their own
342	// titles, so the force reaches them by the task path in the machine block: every
343	// open one not in flight is woken, and none at all is reported, never papered
344	// over with a mint.
345	export function planWake(spec, tasks = [], items = []) {
346	  const ids = String(spec ?? '').split(/[\s,]+/).map((s) => s.trim()).filter(Boolean);
347	  const wake = []; const create = []; const already = []; const unmatched = [];
348	  for (const id of ids) {
349	    const [a, b] = id.includes('/') ? id.split('/') : [null, id];
350	    const owners = tasks.filter((t) => t.id === b && (a === null || t.pack === a));
351	    if (owners.length !== 1) {
352	      unmatched.push({ id, why: owners.length ? `${owners.length} declared packs own a "${b}" task — name it as pack/task` : 'no declared pack owns a task by that name' });
353	      continue;
354	    }
355	    const owner = owners[0];
356	    const { pack, id: task } = owner;
357	    if (!isScheduledTask(owner.decl)) {
358	      const routed = items.filter((i) => {
359	        if (i.state !== 'open') return false;
360	        const byPath = taskIdFromPath(parseWorkItemBody(i.body).taskPath);
361	        return !!byPath && byPath.pack === pack && byPath.task === task;
362	      });
363	      if (!routed.length) {
364	        unmatched.push({ id, why: `"${pack}/${task}" is not on the schedule and has no open item — nothing stands for it to mint, so an item exists only where an issue names the task` });
365	        continue;
366	      }
367	      for (const item of routed) {
368	        if (IN_FLIGHT.includes(statusOf(item))) already.push({ id, issue: item.number });
369	        else wake.push({ id: `${pack}/${task}`, issue: item.number });
370	      }
371	      continue;
372	    }
373	    const item = items.find((i) => {
374	      if (i.state !== 'open') return false;
375	      const parsed = parseWorkItemTitle(i.title);
376	      return parsed && parsed.pack === pack && parsed.task === task;
377	    });
378	    if (!item) { create.push({ id: `${pack}/${task}`, pack, task, taskPath: owner.taskPath }); continue; }
379	    if (IN_FLIGHT.includes(statusOf(item))) { already.push({ id, issue: item.number }); continue; }
380	    wake.push({ id: `${pack}/${task}`, issue: item.number });
381	  }
382	  return { wake, create, already, unmatched };
383	}
