409	// (docs/PRINCIPLES.md) and keeps the person's own title forever, so a prefix test drops exactly
410	// that class — and job 2 is the ONLY site that releases a blocked item, so an
411	// ad-hoc item born blocked on a `Not-before:` sat sleeping past its instant with
412	// nothing left to wake it (#1267, #1349, #1351, #1396). The executor and the
413	// janitor already read the queue through this predicate; this list was the one that
414	// did not.
415	export async function listWorkItems(gh, repo, { since = null } = {}) {
416	  const out = [];
417	  for (let page = 1; ; page += 1) {
418	    const q = `state=all&sort=created&direction=desc&per_page=100&page=${page}`
419	      + (since ? `&since=${encodeURIComponent(since)}` : '');
420	    const { status, json } = await listIssuesByQuery(gh, repo, q);
421	    // A page that could not be read is not the end of the list. Breaking on it
422	    // truncates the queue mid-pagination and the run plans against the remainder:
423	    // a standing item whose page never arrived reads as absent, and the run mints a
424	    // second one beside it.
425	    if (status !== 200 || !Array.isArray(json)) {
426	      throw new Error(`could not list work items in ${repo} at page ${page} (${status}) — a truncated queue is not a shorter one`);
