428	    if (json.length === 0) break;
429	    for (const i of json) {
430	      if (i.pull_request) continue;
431	      if (!isQueueItem(i)) continue;
432	      out.push({
433	        number: i.number, title: i.title, body: i.body ?? '', state: i.state,
434	        labels: labelNames(i), created_at: i.created_at, closed_at: i.closed_at,
