455	  const out = [];
456	  const push = permissionOf ?? (async (login) => {
457	    const res = await collaboratorPermission(gh, repo, login);
458	    if (res.status === 404) return false;
459	    if (res.status !== 200) return null;
460	    return ['admin', 'maintain', 'write'].includes(res.json?.role_name ?? res.json?.permission ?? 'none');
461	  });
462	  const cache = new Map();
463	  // ONE QUERY PER MARK, unioned here. GitHub's `labels` filter is CONJUNCTIVE — a
464	  // comma-separated list selects the issues carrying EVERY name on it — so asking
465	  // for both marks at once asks for issues wearing both, which nothing does. The
466	  // retired `claude-task` spelling keeps working for whoever has it in muscle memory
467	  // or in a template, decoded forever like every legacy spelling (PRINCIPLES.md), and that
468	  // costs a second listing rather than a wider one.
469	  const seen = new Map();
470	  for (const label of [ORIGIN_AD_HOC, REQUEST_LABEL]) {
471	    for (let page = 1; ; page += 1) {
472	      const q = `state=open&labels=${encodeURIComponent(label)}&per_page=100&page=${page}`;
473	      const { status, json } = await listIssuesByQuery(gh, repo, q);
474	      // A list that could not be READ is not a list that is EMPTY, and the two are
475	      // indistinguishable downstream: adoption simply finds nothing to do and the run
476	      // reports success. Every request then waits for a person to notice, which is
477	      // the one thing this lane exists so nobody has to do.
478	      if (status !== 200 || !Array.isArray(json)) {
479	        throw new Error(`could not list open issues marked \`${label}\` in ${repo} (${status}) — an unreadable request list is not an empty one`);
480	      }
481	      if (json.length === 0) break;
482	      for (const i of json) {
483	        if (i.pull_request) continue;
484	        // A filed work item wearing the mark is not a request awaiting adoption: it is
485	        // already an item, and re-adopting one would rewrite its body under the run
486	        // holding it.
487	        if ((i.title ?? '').startsWith(WORK_PREFIX)) continue;
488	        // ANY status means this mark has been adopted — the exactly-once guard (PRINCIPLES.md).
489	        // Filtering here rather than in the plan keeps the permission reads to the
490	        // issues actually awaiting adoption.
491	        if (statusOf(i) !== null) continue;
