519	// Extracted from `main` so it can be called at all. Nothing else here drives
520	// `main`, whose body is I/O against a live Action, so an identifier it names and
521	// never imports resolves at run time or not at all — and the request half went
522	// three days without executing once, behind an adoption list that was always
523	// empty (#1354).
524	export function blockersToResolve(items, requests, known) {
525	  const wanted = new Set();
526	  for (const i of items) {
527	    if (i.state !== 'open' || !isStatus(i, STATUS_BLOCKED)) continue;
