673	      // The reclaim comment is also the EPISODE BOUNDARY: every claim before it is
674	      // dead, and arbitrating over dead claims makes one outrank every future live
675	      // claimant — the item then livelocks through reclaim cycles forever (F18).
676	      await comment(gh, repo, op.issue, `${EPISODE_MARKER}\n${op.reason}`);
677	      await swapStatus({ addLabel, removeLabel }, gh, repo, { number: op.issue }, STATUS_RUNNING_EXECUTOR, op.to);
678	      if (op.to === READY) readied.add(op.issue);
679	      console.log(`- reclaimed #${op.issue} -> ${op.to}`);
680	    } else if (op.kind === 'adopt') {
681	      // THE ISSUE IS THE ITEM, so adoption writes to it rather than filing anything:
682	      // the machine block first, the status second. That order is what makes a torn
683	      // adoption safe — a block with no status is re-adopted by the next scheduler
684	      // run (which rewrites it), while a status with no block would name no task.
685	      const res = await setIssueBody(gh, repo, op.request, op.body);
686	      if (res.status !== 200) {
687	        console.log(`! could not adopt #${op.request}: its body could not be written (${res.status})`);
688	        process.exitCode = 1;
689	        continue;
690	      }
691	      if (op.origin) await addLabel(gh, repo, op.request, op.origin);
692	      await addLabel(gh, repo, op.request, op.status);
693	      await comment(gh, repo, op.request,
694	        `Queued: a run of \`${op.task}\` for this issue${op.model ? `, at the \`${op.model}\` family` : ''}.\n\n`
695	        + (op.blockedBy.length
696	          ? `It is **blocked** on ${op.blockedBy.map((n) => `#${n}`).join(', ')} — it enters the queue once they close.\n\n`
697	          : '')
698	        + (op.notBefore ? `It waits until ${op.notBefore} before entering the queue.\n\n` : '')
699	        + (op.merge
700	          ? `The run implements this issue and opens a pull request; it may land that pull request itself only when the diff sits inside the authorized policy (\`${op.merge}\`), and leaves a wider one for review. `
701	          : 'The run implements this issue and opens a pull request for review — it never merges one. ')
702	        + (op.ungated
703	          ? '\n\nThe `Task:`/`Model:`/`Automerge:` fields in this body were ignored: they are honoured only for an author with push access on this repository, so this run takes the defaults. '
704	          : '')
705	        + `To withdraw the request before it starts, remove the \`${ORIGIN_AD_HOC}\` mark and the status beside it.`);
706	      console.log(`- adopted #${op.request} for ${op.task} (${op.model ?? 'default model'}${op.blockedBy.length ? `, blocked on ${op.blockedBy.map((n) => `#${n}`).join(' ')}` : ''}${op.merge ? `, may merge: ${op.merge}` : ''})`);
707	    } else if (op.kind === 'supersede') {
708	      await comment(gh, repo, op.issue, op.reason);
709	      await addLabel(gh, repo, op.issue, TASK_OBSOLETE);
710	      await closeIssue(gh, repo, op.issue, 'not_planned');
711	      console.log(`- superseded #${op.issue} — #${op.request} was re-marked`);
712	    } else if (op.kind === 'dedupe') {
713	      await comment(gh, repo, op.issue, op.reason);
714	      await addLabel(gh, repo, op.issue, TASK_OBSOLETE);
715	      await closeIssue(gh, repo, op.issue, 'not_planned');
716	      console.log(`- deduped #${op.issue}`);
717	    } else if (op.kind === 'retire-orphan') {
718	      await comment(gh, repo, op.issue, op.reason);
719	      await addLabel(gh, repo, op.issue, TASK_OBSOLETE);
720	      await closeIssue(gh, repo, op.issue, 'not_planned');
721	      console.log(`- reaped #${op.issue} — ${op.pack}/${op.task} is not declared at HEAD`);
722	    }
723	  }
724	
725	  if (!ops.length) console.log('- nothing to do: no task said yes, nothing is marked, nothing is due to be readied, no claim is dead');
726	
727	  // The forced wake, last: an item this run just instantiated is wakeable in the
728	  // same run, so a force never has to be pressed twice. The drain job that follows
729	  // picks up whatever this readies.
730	  const spec = actionsEnv().CLAUDINITE_WAKE ?? '';
731	  if (spec.trim()) {
732	    const { wakeItem } = await import('./create-work-item.mjs');
733	    // Re-read for what the ops above readied, unioned with what they created: the
734	    // read alone can miss an item filed seconds earlier, and the force then mints a
735	    // duplicate of it rather than waking it (#1979).
736	    const current = withOwnWrites(await listWorkItems(gh, repo, { since }), minted);
737	    const { wake, create, already, unmatched } = planWake(spec, tasks, current);
738	    for (const w of wake) {
739	      const res = await wakeItem(gh, repo, w.issue);
740	      if (res.ok) readied.add(w.issue);
741	      console.log(res.ok ? `- woke #${w.issue} ${w.id}` : `! could not wake #${w.issue} ${w.id}: ${res.error}`);
742	    }
743	    if (create.length) await ensureLabels(gh, repo, QUEUE_LABELS);
744	    for (const c of create) {
745	      const res = await createIssue(gh, repo, {
746	        title: workItemTitle({ pack: c.pack, task: c.task }),
747	        // `Woken:` is what lets the task's cadence terms hold at pick — a person's
748	        // wake stands in for the cadence — while everything else it requires
749	        // still applies (docs/PRINCIPLES.md).
750	        body: workItemBody({ taskPath: c.taskPath, context: [FORCED_WAKE_CONTEXT], woken: now.toISOString() }),
751	        // A forced mint stands in for the occurrence the schedule would have filed,
752	        // so it wears the same origin: the task IS on the schedule, and this item is
753	        // its current occurrence (PRINCIPLES.md).
754	        labels: [ORIGIN_PLANNED, READY],
755	      });
756	      if (res.number) {
757	        readied.add(res.number);
758	        console.log(`- created #${res.number} ${c.id} (forced: it had no open standing item)`);
759	      } else { console.log(`! could not create a work item for ${c.id}: ${res.status}`); process.exitCode = 1; }
760	    }
761	    for (const a of already) console.log(`- ${a.id} is already in flight on #${a.issue} — left alone`);
762	    for (const u of unmatched) console.log(`! nothing woken for "${u.id}": ${u.why}`);
763	    // A force that woke nothing is a failed force, and a green run saying so in a
764	    // log line is how it goes unnoticed by the fleet lever that pressed it.
765	    if (unmatched.length) process.exitCode = 1;
766	  }
767	
768	  // LAST, AFTER THE WAKE: whether this run leaves anything for an executor to do.
769	  await announcePickable(gh, repo, tasks, readied);
770	}
771	
772	// THE DRAIN GATE (PRINCIPLES.md). Every workflow run is a billed invocation whatever it
773	// finds — Actions rounds each job's minutes up — so the drain job dispatches an
774	// executor only when this run's parting look at the queue found something
775	// pickable. On a quiet repo that is the difference between 24 executor runs a day
776	// and none.
777	//
778	// This is the run's LAST act, after the forced wake: a wake readies items, and a
779	// look taken before it would send the hour's forced work to the next cron fire.
780	//
781	// The delivery is unweakened by the gate. A label event may be lost, and what a
782	// lost event would have delivered is exactly what this look sees — the queue
783	// itself, read live, by the same pick rule the executor applies. Where the
784	// output cannot be written (a run outside Actions, an older member workflow that
785	// maps no output) the drain job's own default decides, and the run says which
786	// happened rather than going quiet about it.
787	// THE VERDICT IS A UNION, not a read. What the list returns is one source; what
788	// this run itself readied is the other, and the second needs no confirmation —
789	// GitHub's issue list is eventually consistent, so an item created milliseconds
790	// earlier can be absent from it (#1340). Trusting the read alone left a forced
791	// `update` sitting `task:ready` until the next cron fire on three members at once.
792	// Ordering stays the executor's job: this only decides whether to start one.
793	export function pickableCount(open, readiedThisRun = [], opts = {}) {
794	  const listed = pickOrder(open, opts).map((i) => i.number);
795	  return new Set([...listed, ...readiedThisRun]).size;
796	}
797	
798	// THE QUEUE AS THIS RUN KNOWS IT: what the list returned, plus the items this run
799	// itself created and the read has not caught up to (#1979). Only the ones the read
800	// missed are added — where both name an issue the read wins, since it is the later
801	// truth about one this run is no longer writing to.
802	export function withOwnWrites(listed, mintedThisRun = []) {
803	  const seen = new Set(listed.map((i) => i.number));
804	  return [...listed, ...mintedThisRun.filter((i) => !seen.has(i.number))];
805	}
806	
807	async function announcePickable(gh, repo, tasks, readiedThisRun = new Set()) {
808	  const { listOpenWorkItems } = await import('../items/read.mjs');
809	  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
810	  const byPath = new Map(tasks.map((t) => [t.taskPath, `${t.pack}/${t.id}`]));
811	  const pickable = pickableCount(await listOpenWorkItems(gh, repo), readiedThisRun, {
812	    taskAfter: (id) => byId.get(id)?.decl?.schedule_after ?? [],
813	    scheduledOf: (id) => (byId.has(id) ? isScheduledTask(byId.get(id).decl) : null),
814	    pathTo: (p) => byPath.get(p) ?? null,
815	  });
816	  console.log(pickable
817	    ? `- ${pickable} item(s) pickable — the drain job dispatches an executor`
818	    : '- nothing pickable — no executor is dispatched this run');
819	  setStepOutput('pickable', pickable ? 'true' : 'false');
820	}
821	
822	// Run only when invoked directly (the workflow's `node scheduler-run.mjs`), never on
823	// import. Exported as well, because `tick.mjs` beside this file is a fielded entry
824	// point that must be able to start the same run without being this module.
825	export { main as runSchedulerRun };
826	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
827	  main().catch((e) => { console.error(e); process.exit(1); });
828	}
829	
830	export { parseWorkItemTitle };
831

