350	    ensureLabels: async (_gh, _repo, want) => {
351	      for (const { name, color, description } of want) {
352	        const res = await route(`/repos/${repo}/labels`, { method: 'POST', body: { name, color, description } });
353	        if (res.status === 422) {
354	          await route(`/repos/${repo}/labels/${encodeURIComponent(name)}`, { method: 'PATCH', body: { color, description } });
355	        }
356	      }
357	    },
358	    addLabel: (_gh, _repo, number, name) => route(`/repos/${repo}/issues/${number}/labels`, { method: 'POST', body: { labels: [name] } }),
359	    removeLabel: (_gh, _repo, number, name) => route(`/repos/${repo}/issues/${number}/labels/${encodeURIComponent(name)}`, { method: 'DELETE' }),
360	    swapLabel: async (_gh, _repo, number, from, to) => {
361	      await port.removeLabel(_gh, _repo, number, from);
362	      // The torn swap, and the only shape it has: the remove landed, the add did
363	      // not, and the item is left wearing no status at all.
364	      if (faults.tearNextSwap) {
365	        faults.tearNextSwap = false;
366	        state.calls.push(`POST /repos/${repo}/issues/${number}/labels`);
367	        return { status: 500, json: { message: 'torn label swap (injected)' } };
368	      }
369	      return port.addLabel(_gh, _repo, number, to);
370	    },
371	
372	    comment: (_gh, _repo, number, body) => route(`/repos/${repo}/issues/${number}/comments`, { method: 'POST', body: { body } }),
373	    editComment: (_gh, _repo, commentId, body) => route(`/repos/${repo}/issues/comments/${commentId}`, { method: 'PATCH', body: { body } }),
374	    listComments: async (_gh, _repo, number) => {
375	      const { status, json } = await route(`/repos/${repo}/issues/${number}/comments?per_page=100&page=1`);
376	      return status === 200 && Array.isArray(json) ? json : [];
377	    },
378	
379	    collaboratorPermission: (_gh, _repo, login) => route(`/repos/${repo}/collaborators/${encodeURIComponent(login)}/permission`),
380	
381	    listOpenPulls: (_gh, _repo) => route(`/repos/${repo}/pulls?state=open&per_page=100`),
382	    readPull: (_gh, _repo, number) => route(`/repos/${repo}/pulls/${number}`),
383	    mergePull: (_gh, _repo, number, body) => route(`/repos/${repo}/pulls/${number}/merge`, { method: 'PUT', body }),
384	    closePull: (_gh, _repo, number) => route(`/repos/${repo}/pulls/${number}`, { method: 'PATCH', body: { state: 'closed' } }),
385	
386	    deleteBranchRef: (_gh, _repo, ref) => route(`/repos/${repo}/git/refs/heads/${encodeURIComponent(ref)}`, { method: 'DELETE' }),
387	    readBranch: (_gh, _repo, branch) => route(`/repos/${repo}/branches/${branch}`),
388	    readTree: (_gh, _repo, ref) => route(`/repos/${repo}/git/trees/${ref}`),
389	
390	    readCommit: (_gh, _repo, sha) => route(`/repos/${repo}/commits/${sha}`),
391	    listRunsForSha: (_gh, _repo, sha) => route(`/repos/${repo}/actions/runs?head_sha=${sha}&per_page=100`),
392	    latestRelease: (_gh, _repo) => route(`/repos/${repo}/releases/latest`),
393	    readRepoVariable: (_gh, _repo, name) => route(`/repos/${repo}/actions/variables/${name}`),
394	
395	    dispatchWorkflow: async (_gh, _repo, file, ref, inputs = null) => {
396	      const { status } = await route(`/repos/${repo}/actions/workflows/${file}/dispatches`, {
397	        method: 'POST', body: { ref, ...(inputs ? { inputs } : {}) },
398	      });
399	      return { ok: status === 204, status };
400	    },
401	  };
402	
403	  let graphql = async () => ({ data: {} });
404	
405	  const harness = {
406	    port,
407	    state,
408	    gh,
409	    // Direct reads, for assertions and for the other fakes in this folder.
410	    find: issue,
411	    findPull: pull,
412	    issues: () => state.issues,
413	    pulls: () => state.pulls,
414	    labelDefs: () => state.labelDefs,
415	    dispatches: () => state.dispatches,
416	    calls: () => state.calls,
417	    onDispatch: (fn) => { onDispatch.push(fn); return harness; },
418	    scriptGraphql: (fn) => { graphql = fn; return harness; },
419	
420	    // Direct writes, for seeding a world and for `humans.mjs`.
421	    // A number is ASSIGNED when the caller gives none — a seeded issue with no
422	    // number is unreachable by every read there is, which reads as an empty repo
423	    // rather than as the mistake it was.
424	    seedIssue: (fields) => {
425	      const i = {
426	        number: nextNumber(), comments: [], state: 'open', labels: [], body: '', title: '',
427	        created_at: nowIso(), updated_at: nowIso(), ...fields,
428	      };
429	      state.issues.push(i);
430	      return i;
431	    },
432	    seedPull: (fields) => {
433	      const p = { number: nextNumber(), comments: [], state: 'open', merged: false, ...fields };
434	      state.pulls.push(p);
435	      return p;
436	    },
437	    defineLabels: (defs) => { for (const d of defs) state.labelDefs.set(d.name, { ...d }); return harness; },
438	    setCollaborator: (login, permission) => { state.collaborators[login] = permission; return harness; },
439	    setVariable: (name, value) => { state.variables[name] = value; return harness; },
440	    clearVariable: (name) => { delete state.variables[name]; return harness; },
441	
442	    // --- faults ---------------------------------------------------------
443	    rateLimit: (calls) => { faults.rateLimited = calls; return harness; },
444	    hideFromLists: (number) => { faults.hidden.add(Number(number)); return harness; },
445	    revealInLists: (number) => { faults.hidden.delete(Number(number)); return harness; },
446	    tearNextLabelSwap: () => { faults.tearNextSwap = true; return harness; },
447	    dropNextLabeledEvent: () => { faults.dropNextLabeled = true; return harness; },
448	    // Asked by whoever would deliver the webhook; consumes the drop.
449	    takeLabeledEvent: () => {
450	      if (!faults.dropNextLabeled) return true;
451	      faults.dropNextLabeled = false;
452	      return false;
453	    },
454	    unknownLabels422: (on = true) => { faults.unknownLabels422 = on; return harness; },
455	    faults,
456	  };
457	  return harness;
458	}
