1	// The executor (docs/PRINCIPLES.md) — a pull worker over the queue. Each
2	// iteration: pick the next ready item, claim it by a verified lease, re-evaluate
3	// the precondition (the scheduler run asked once at the anchor; a chained stage
4	// re-derives world state rather than trusting a verdict passed forward), then on
5	// a go run code-work and either converge (agentless) or hand off to an agent
6	// session; on a no-go close the item with the reason on record — the next
7	// occurrence is the scheduler run's ask at the task's next anchor (#1115).
8	//
9	// An executor's whole interface is issue read/write plus the repo at HEAD, which
10	// is what makes it platform-agnostic: the reference deployment is a job in the
11	// vendored workflows (the scheduler run's post-scheduler run drain, and a `labeled`-event run for
12	// latency), but a runner anywhere with an issues-scope token qualifies. Nothing
13	// enumerates executors; identity is self-declared in the claim comment.
14	//
15	// The pure decisions live at the top and test with fixtures; the shell below is
16	// the GitHub/code-work/invocation I/O around them.
17	
18	import { existsSync } from 'node:fs';
19	import { pathToFileURL } from 'node:url';
20	import { isSuspended, liveSuspendReader, suspendedNotice, SUSPEND_ALL_VAR } from '../world/hold.mjs';
21	import { HEARTBEAT_MS, heartbeatComment, withHeartbeat } from '../items/heartbeat.mjs';
22	import { renderTaskExec } from '../items/run-record.mjs';
23	import { evaluatePrecondition } from '../contract/precondition.mjs';
24	import { isScheduledTask } from '../contract/task-contract.mjs';
25	import { swapStatus, clearStatus } from '../items/apply-status.mjs';
26	import { pickOrder, taskIdOf, titleOf, running } from '../items/pick-order.mjs';
27	import { resolveTarget, closeSuperseded } from './target.mjs';
28	import { deliveryFor } from '../deliver/land-pr.mjs';
29	import { actionsEnv, repoRoot } from '../world/actions.mjs';
30	import { now as clockNow } from '../world/clock.mjs';
31	import { setIssueBody } from '../world/github.mjs';
32	import {
33	  BLOCKED, READY, URGENT, EXECUTING, AGENT, requeueHint,
34	  STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT, isStatus,
35	  TASK_DONE, TASK_OBSOLETE, QUEUE_LABELS, QUEUED_LABEL, isStandingItem,
36	  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_FAILURE,
37	  CLAIM_MARKER, HANDOFF_MARKER, EPISODE_MARKER,
38	  parseWorkItemTitle, parseWorkItemBody, taskIdFromPath, parseContextLines, mergeContext, withNotBefore, withSection, editItemBody, hasLabel, DELIVERED_HEADING, LEGACY_DELIVERED_HEADINGS,
39	  LAST_VERDICT_HEADING, lastVerdictLines,
40	  withTarget,
41	  itemFacts,
42	} from '../items/work-item.mjs';
43	
44	// The claim comment carries WHO and WHEN — the executor id and its run URL —
45	// because executor identity is an unbounded set and must never become a label
46	// (PRINCIPLES.md).
47	export const claimComment = ({ executor, runUrl, at }) =>
48	  `${CLAIM_MARKER}\nClaimed by executor \`${executor}\` at ${at}.${runUrl ? `\n\nRun: ${runUrl}` : ''}`;
49	
50	// Who won the claim, out of an item's comments (PRINCIPLES.md). Three precisions,
51	// each an implicit assumption made explicit:
52	//
53	//  - "EARLIEST" MEANS LOWEST COMMENT ID, never timestamp. GitHub comment
54	//    `created_at` has one-second granularity, so simultaneous claims tie on time;
55	//    comment ids are server-assigned and strictly increasing — a total order the
56	//    protocol gets for free. Nothing here compares runner clocks.
57	//  - THE ARBITER IS EPISODE-SCOPED (F18): the earliest claim SINCE the item last
58	//    became ready. Over an item's lifetime dead claims accumulate (every reclaim
59	//    and revert leaves one), and arbitrating over all of them makes a dead claim
60	//    outrank every future live claimant — the item then livelocks through reclaim
61	//    cycles forever. The reclaim / revert / re-queue comment is the boundary.
62	//  - THE LABEL SWAP IS NOT THE ARBITER, so a torn swap can never mint a second
63	//    owner; it can only leave an item with no state label, which the janitor
64	//    repairs.
65	export function claimWinner(comments = []) {
66	  const sorted = [...comments].sort((a, b) => a.id - b.id);
67	  const boundary = sorted.filter((c) => (c.body ?? '').includes(EPISODE_MARKER)).at(-1);
68	  const claims = sorted
69	    .filter((c) => (c.body ?? '').includes(CLAIM_MARKER))
70	    .filter((c) => !boundary || c.id > boundary.id);
71	  return claims[0] ?? null;
72	}
73	
74	// After WINNING a claim, re-verify the pick filters against live state (F15). The
75	// filters read possibly-stale state, so two executors can pass them simultaneously
76	// and claim DIFFERENT items the filters should have serialized — a twin pair, or
77	// an upstream and its dependent. The per-item lease cannot see that: it protects
78	// one item, not one title. If a conflicting item now holds an EARLIER claim
79	// (comment id — the same arbiter the lease trusts), this executor reverts its own
80	// claim and moves on. Bounded, deterministic, and the earlier claim never notices.
81	export function conflictsWithEarlierClaim(item, myClaimId, others, { taskAfter = () => [], scheduledOf = () => null, pathTo = () => null } = {}) {
82	  const idOf = (i) => taskIdOf(i, pathTo);
83	  const standing = (i) => isStandingItem(i, scheduledOf(idOf(i)));
84	  const upstreams = standing(item) ? taskAfter(idOf(item)) : [];
85	  return others.some((o) => {
86	    if (o.number === item.number) return false;
87	    if (!running(o)) return false;
88	    const conflicting = titleOf(o) === titleOf(item)
89	      || (upstreams.includes(idOf(o)) && standing(o));
90	    return conflicting && o.claimId != null && o.claimId < myClaimId;
91	  });
92	}
93	
94	// The no-go outcome (PRINCIPLES.md): every decline CLOSES the item with the
95	// reason. The roll — `Not-before` stamped, open-blocked, waiting out the period —
96	// is gone, and so is the schedule board: a scheduled task's next occurrence is
97	// the scheduler run's ask at its next tick, and the closed item is itself the
98	// history the task's cadence term reads (a `due:` period this item started in is
99	// consumed by it). `standing` marks whether the close should say so.
100	// The `(item, task, schedule, now, reason)` signature is kept — callers and
101	// fielded tests pass all five, and the standing/ad-hoc distinction still
102	// shapes the close's wording.
103	export function noGoPlan(item, task, schedule, now, reason) {
104	  return {
105	    kind: 'close',
106	    outcome: TASK_OBSOLETE,
107	    stateReason: 'not_planned',
108	    reason,
109	    standing: isStandingItem(item, task?.decl ? isScheduledTask(task.decl) : null),
110	  };
111	}
112	
113	// --- the shell ----------------------------------------------------------------
114	
115	const nowIso = () => clockNow().toISOString();
116	
117	// ONE EXECUTOR RUN DRAINS THE QUEUE (docs/PRINCIPLES.md, reversing
118	// one-item-per-run). Actions bills each job's runtime rounded UP to the next
119	// minute, so a day's cost is the RUN count: a run that performed one item paid a
120	// whole invocation — checkout, setup, rounding — per item. So a run claims an
121	// item, sees it to its settle, then picks the next, and ends when nothing is
122	// pickable. Items still settle ONE AT A TIME: this moved the run boundary, not
123	// the occupancy model, and capacity is still executor width.
124	//
125	// What still starts a run is the enumerable list docs/PRINCIPLES.md names, each cause on the
126	// record: the scheduler run's drain job (dispatched only when that run leaves
127	// something pickable), a label event, an agent session's close-time drain, and
128	// the workflow's failure-continuation job when a run dies mid-drain. Self-
129	// re-dispatch retired with the one-item run — the remainder is this run's own.
130	//
131	// AN ITEM THIS RUN LET GO OF IS NEVER RE-ATTEMPTED BY IT. Losing a claim race
132	// leaves the item running under its winner, so the next pick simply does not see
133	// it — but a post-claim REVERT puts the item back to ready, and re-picking what
134	// this run just returned to the queue is an unbounded loop, not a retry. Both
135	// exits are therefore recorded in `standDown` and skipped for the rest of the
136	// run; the executor that won, and the scheduler run behind it, carry those.
137	//
138	// The loop terminates because every iteration either settles an item (which
139	// leaves the ready state) or stands down from one — and the only items that
140	// newly become pickable are the dependents a close releases, which is the
141	// chaining this exists to do. Its outer bound is the workflow's own timeout.
142	//
143	// Injected seams keep the run testable end to end without GitHub, code-work
144	// subprocesses or an invocation endpoint. `heldNow` is the operator hold, asked
145	// between items (PRINCIPLES.md): `vars.*` reaches the env at start only, so a drain that
146	// outlives the hold's arrival can only see it by asking.
147	export async function runExecutor({
148	  gh, repo, root, config, tasks, executorId, runUrl = null,
149	  now = () => clockNow(), random = Math.random, heartbeatMs = HEARTBEAT_MS,
150	  collectSignalsFor, runTaskCodeWork, invokeAgent, heldNow = null, log = console.log,
151	  resolveTargetFor = null,
152	}) {
153	  const api = await import('../world/github.mjs');
154	  const { listOpenWorkItems } = await import('../items/read.mjs');
155	  const schedule = config.taskScheduler;
156	  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
157	  const taskAfter = (id) => byId.get(id)?.decl?.schedule_after ?? [];
158	  const scheduledOf = (id) => (byId.has(id) ? isScheduledTask(byId.get(id).decl) : null);
159	  // A marked issue names its task by worker path, so the run needs the inverse of
160	  // the id map — built from the same task set, so a path this repo does not carry
161	  // resolves to nothing and the item is malformed rather than guessed at.
162	  const byPath = new Map(tasks.map((t) => [t.taskPath, `${t.pack}/${t.id}`]));
163	  const pathTo = (p) => byPath.get(p) ?? null;
164	  // THE TARGET SEAM (PRINCIPLES.md): which branch and pull request a run works on,
165	  // resolved from the task's declared outcome against the repo's open pull
166	  // requests. The member's delivery preference is what says whether a green
167	  // incumbent may be landed on the way; it is read once, from the same config the
168	  // hand-off reads.
169	  const resolveTargetOf = resolveTargetFor ?? ((task, at) => resolveTarget({
170	    gh, repo, taskId: `${task.pack}/${task.id}`, outcome: task.decl.expected_outcome,
171	    delivery: deliveryFor(config), now: at, log,
172	  }));
173	  const done = [];
174	  // Items this run has let go of — a lost race, a reverted claim — and must not
175	  // pick again. Without it a revert re-picks what it just returned to the queue.
176	  const standDown = new Set();
177	
178	  for (;;) {
179	    // Read live every time: the settle just made may have readied a dependent,
180	    // and another executor may have taken what was pickable a moment ago.
181	    const open = await listOpenWorkItems(gh, repo);
182	    const candidate = pickOrder(open, { taskAfter, scheduledOf, random, pathTo })
183	      .find((i) => !standDown.has(i.number));
184	    if (!candidate) break;
185	
186	    // --- claim: the verified lease ------------------------------------------
187	    await swapStatus(api, gh, repo, candidate, STATUS_READY, EXECUTING);
188	    await api.comment(gh, repo, candidate.number, claimComment({
189	      executor: executorId, runUrl, at: nowIso(),
190	    }));
191	    const comments = await api.listComments(gh, repo, candidate.number);
192	    const winner = claimWinner(comments);
193	    const mine = [...comments]
194	      .sort((a, b) => a.id - b.id)
195	      .filter((c) => (c.body ?? '').includes(CLAIM_MARKER) && (c.body ?? '').includes(`executor \`${executorId}\``))
196	      .at(-1);
197	    if (!winner || winner.id !== mine?.id) {
198	      // The loser reverts nothing — the winner's labels already stand. It does
199	      // strike its own claim (F24): letting go covers losing too, and a claim left
200	      // behind here outlives the winner's episode and becomes the earliest of the
201	      // NEXT one, moving the livelock one episode along.
202	      await strikeClaim(api, gh, repo, mine);
203	      standDown.add(candidate.number);
204	      log(`- #${candidate.number}: another executor holds this episode's earliest claim — leaving it to them`);
205	      continue;
206	    }
207	
208	    // --- post-claim re-verify (F15) -----------------------------------------
209	    const others = await withClaimIds(api, gh, repo, await listOpenWorkItems(gh, repo), candidate.number);
210	    if (conflictsWithEarlierClaim(candidate, winner.id, others, { taskAfter, scheduledOf, pathTo })) {
211	      await api.comment(gh, repo, candidate.number,
212	        `${EPISODE_MARKER}\nReverting this claim: a conflicting item holds an earlier claim this cycle. Returning the item to the queue.`);
213	      await swapStatus(api, gh, repo, candidate, STATUS_RUNNING_EXECUTOR, READY);
214	      standDown.add(candidate.number);
215	      log(`- #${candidate.number}: reverted — a conflicting item claimed earlier`);
216	      continue;
217	    }
218	
219	    const outcome = await executeItem({
220	      api, gh, repo, root, config, schedule, byId, pathTo, item: candidate, executorId,
221	      claim: winner, now, heartbeatMs, collectSignalsFor, runTaskCodeWork, invokeAgent, log,
222	      resolveTargetOf,
223	    });
224	    done.push({ issue: candidate.number, outcome });
225	
226	    // --- the hold, between items (PRINCIPLES.md) -----------------------------------
227	    // Asked after the settle rather than before the pick that follows it, so a
228	    // run that had nothing more to do never spends the read. The item just
229	    // finished is untouched: suspension stops picking, never running work.
230	    if (heldNow && await heldNow()) {
