238	// The claim id of each live item, so the post-claim verify can compare episodes.
239	// One comment read per conflicting-looking item, not per item in the repo.
240	async function withClaimIds(api, gh, repo, items, selfNumber) {
241	  const out = [];
242	  for (const i of items) {
243	    if (i.number === selfNumber || !running(i)) { out.push(i); continue; }
244	    const winner = claimWinner(await api.listComments(gh, repo, i.number));
245	    out.push({ ...i, claimId: winner?.id ?? null });
246	  }
247	  return out;
