311	  // --- the single precondition evaluation (PRINCIPLES.md) --------------------
312	  const at = now();
313	  // The item's own facts — its fields, its number, whether somebody woke it — are
314	  // what the terms judge over: a request item's verdict is about the issue it
315	  // names, which no signal bundle can single out on its own (PRINCIPLES.md), and
316	  // the cadence terms hold on a woken item (PRINCIPLES.md). The signals are collected FOR
317	  // THIS OCCURRENCE, its own run history excluding it.
318	  const fields = itemFacts(item);
319	  const signals = await collectSignalsFor(task, at, item);
320	  const verdict = evaluatePrecondition(task, signals, config.packConfig?.[task.pack] ?? {}, fields, at, schedule);
321	
322	  // A PRECONDITION THAT COULD NOT ANSWER IS A RUN FAILURE, NOT A VERDICT (F27). A
323	  // decline is a decision about the world; one taken on an API that would not answer
324	  // is a guess, and its write-backs cannot land — for a request that would strand
325	  // the issue armed-but-queued forever, the request silently eaten. So the item
326	  // parks open in the failure lane, where the ordinary re-queue lever retries it
327	  // once the API recovers, and nothing is written to whatever it could not read.
328	  if (verdict.error) {
329	    await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_FAILURE, claim,
330	      `This run could not be decided: ${verdict.error}\n\nNothing ran and nothing was written. Re-queue this item (${requeueHint}) once the cause has cleared.`);
