372	  // "nothing to amend" on that evidence stacks a duplicate.
373	  const target = await resolveTargetOf(task, at);
374	  if (target.error) {
375	    await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_FAILURE, claim,
376	      `This run could not be given a target: ${target.error}\n\nNothing ran and nothing was written. Re-queue this item (${requeueHint}) once the cause has cleared.`);
377	    log(`! #${item.number} ${id}: the target could not be resolved — ${target.error}`);
378	    return 'needs-human';
379	  }
380	  log(`- #${item.number} ${id}: target — ${target.reason}`);
381	  if (target.landed) {
