383	    // That IS this occurrence: the tree this run holds predates the merge, so the
384	    // work would re-deliver a diff already on the base. The next occurrence
385	    // converges from the moved base.
386	    await closeSuperseded({ gh, repo, numbers: target.supersedes, successor: target.landed, log });
