388	      `Landed #${target.landed}, this task's previous delivery, which had concluded green and was never merged. `
389	      + 'The checkout this run holds predates that merge, so nothing else ran; the next occurrence converges from the moved base.', 'success');
390	    return TASK_DONE;
391	  }
392	
393	  if (task.decl.code_work) {
394	    // The work step may legitimately run for hours (PRINCIPLES.md). While it does, the
395	    // item's only sign of life is this beat — which is also what the scheduler run's leash
396	    // measures, so a long run is legal rather than reclaimed underneath itself.
397	    const result = await withHeartbeat(() => runTaskCodeWork(task, { item, context, target }), {
