478	
479	  // An agentless task with no code-work does nothing (the contract forbids it).
480	  if (task.decl.agent_model === 'none') {
481	    await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_FAILURE, claim,
