509	// Hand off to an agent session (PRINCIPLES.md). ONE call per item, ever — which is
510	// what lets this be as short as it is. The nonce goes on the item before the call
511	// and travels in the payload, so the session can prove the fire it arrived on is
512	// the hand-off this item recorded and stop if it is not.
513	async function handOff({ api, gh, repo, item, task, id, context, result, target = null, executorId, claim, invokeAgent, config, log }) {
514	  const nonce = `${item.number}-${Math.random().toString(36).slice(2, 10)}`;
515	  // Every section lands in the machine's half of the body — the whole body for a
516	  // filed item, the machine block for a marked issue, whose prose is the person's.
517	  const body = editItemBody(item.body, (machine) => {
518	    let out = machine;
519	    // The target's fields first, under the task path: the branch the session
520	    // pushes to, the pull request it amends, the ones its converge supersedes.
521	    if (target) out = withTarget(out, target);
522	    if (context.length) out = withSection(out, 'Context', context);
523	    if (result.delivered?.length) out = withSection(out, DELIVERED_HEADING, result.delivered, LEGACY_DELIVERED_HEADINGS);
524	    if (result.reason) out = withSection(out, 'Why the agent is here', [result.reason]);
525	    return out;
526	  });
527	  await setIssueBody(gh, repo, item.number, body);
528	
529	  await swapStatus(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, AGENT);
530	  await api.comment(gh, repo, item.number,
531	    `${HANDOFF_MARKER}\nHanded off by executor \`${executorId}\` — invocation nonce \`${nonce}\`.`);
532	
533	  const invocation = await invokeAgent({ task, item, nonce, config });
534	  if (invocation.ok) {
535	    await api.comment(gh, repo, item.number,
536	      `Agent session started${invocation.sessionUrl ? `: ${invocation.sessionUrl}` : ''}.`);
537	    log(`- #${item.number} ${id}: handed off${invocation.sessionId ? ` (${invocation.sessionId})` : ''}`);
538	    return 'agent';
539	  }
540	  if (invocation.answered) {
541	    // The endpoint refused, so no session exists and none will: a token, a URL or
542	    // a routine is wrong, and every future pick would be refused the same way.
543	    await converge(api, gh, repo, item, STATUS_RUNNING_AGENT, NEEDS_HUMAN_ACTION, claim,
544	      `Could not start an agent session: ${invocation.error}\n\nNo session was started. Fix the invocation endpoint, then re-queue this item (${requeueHint}).`);
545	    return 'needs-human';
546	  }
547	  // NOTHING CAME BACK, and this is the case the whole design turns on: the call
548	  // may have started a session. Re-queueing here is what would put two sessions on
549	  // one item, and converging to triage would kill a run that is very possibly
550	  // alive. So the item STAYS with the agent and says the outcome is unknown —
551	  // whichever way it went is then settled by a rule that already exists: a session
552	  // that started converges the item, and one that never did leaves the item silent
553	  // until the janitor's agent leash sweeps it to triage.
554	  await api.comment(gh, repo, item.number,
555	    `The agent invocation got no answer: ${invocation.error}\n\n`
556	    + 'The session may or may not have started, so nothing here re-tries it — a second call could put two sessions on this item. '
557	    + 'If a session did start it will converge this item; if it did not, the janitor\'s agent leash parks it for a human within a few hours.');
558	  log(`! #${item.number} ${id}: invocation unanswered — left with the agent, leash decides — ${invocation.error}`);
559	  return 'unknown';
560	}
561	
562	// LETTING GO OF AN OPEN ITEM KILLS YOUR CLAIM (PRINCIPLES.md, F24). An executor
563	// that stops owning an item without closing it — the roll, and every
564	// `needs-human` park — strikes its own claim by appending the episode marker to
565	// it. `claimWinner` already treats the last marker as the boundary, so a struck
566	// claim stops outranking anything and the next claimant wins on its first try.
567	//
568	// APPENDING rather than commenting is what lets the roll stay silent (PRINCIPLES.md): an
569	// hourly task that declines every hour adds no timeline entry. A successful
570	// hand-off deliberately does NOT strike — the episode is still live, owned by the
571	// agent session — and neither does a close, since nothing re-claims a closed item.
572	//
573	// Struck BEFORE the label swap, so the crash window degrades the safe way: an
574	// executor that dies between the two leaves the item `task:executing` with a
575	// spent claim, which the scheduler run's leash reclaim already recovers. Striking after
576	// would leave exactly the state this fixes — parked, re-queued by a human, and
577	// unclaimable forever.
578	async function strikeClaim(api, gh, repo, claim) {
579	  if (!claim || (claim.body ?? '').includes(EPISODE_MARKER)) return;
580	  await api.editComment(gh, repo, claim.id,
581	    `${claim.body}\n\n${EPISODE_MARKER}\nThis claim is spent — the executor released this item without closing it.`);
582	}
583	
584	// Every exit converges the item exactly once, with one comment saying what
585	// happened — the terminal-state discipline the incidents bought. The claim sits
586	// before the body so every state argument is grouped ahead of the prose.
587	//
588	// THE COMMENT CARRIES THE EXECUTION RECORD (docs/PRINCIPLES.md). Actions logs
589	// expire, and for an agentless run — the majority — the item is the only durable
590	// trace there will ever be, so the record goes where the item is rather than into
591	// a log that ages out. The bracketed field is this item's issue number, which is
592	// the only join from a record back to the work it describes.
593	// A status of `null` writes NO record, and that is the honest answer for a park
594	// that is not a failure: the vocabulary's `success` means "ran to completion and
595	// the issue was closed" and `failed` means the run broke, so an approval park —
596	// a run that succeeded and left a PR for a person — is neither. Absence is a
597	// state of its own; inventing a fifth status is a change to stored data every
598	// decoder in the fleet would have to learn.
599	const recordFor = (item, status) => {
600	  // `item.taskId` is the resolved id — a marked issue's title names no task, so the
601	  // title parse alone would silently drop the record for every request run.
602	  const id = item.taskId ?? null;
603	  const parsed = status
604	    ? (id ? { pack: id.split('/')[0], task: id.split('/').slice(1).join('/') } : parseWorkItemTitle(item.title))
605	    : null;
606	  return parsed
607	    ? `\n\n\`\`\`\n${renderTaskExec({ pack: parsed.pack, task: parsed.task, slotId: `#${item.number}`, status })}\n\`\`\``
608	    : '';
609	};
610	
611	// Park an item for a human. ONE label: the park IS the status, and its kind is what
612	// the human is being asked for (PRINCIPLES.md). The two-label park it replaces could be
613	// half-applied, which was a torn state of its own.
614	async function converge(api, gh, repo, item, from, park, claim, body, status = 'failed') {
615	  await strikeClaim(api, gh, repo, claim);
616	  await api.comment(gh, repo, item.number, body + recordFor(item, status));
617	  await swapStatus(api, gh, repo, item, from, park);
618	}
619	
620	// A close writes only to the item it holds (docs/PRINCIPLES.md; #1373 reversed
621	// an earlier attempt): a dependent this close may make due is released solely by the
622	// scheduler run's own readiness job, on its next hourly pass, never here.
623	async function close(api, gh, repo, item, from, outcome, stateReason, body, status) {
624	  await api.comment(gh, repo, item.number, body + recordFor(item, status));
625	  await clearStatus(api, gh, repo, item, from);
626	  await api.addLabel(gh, repo, item.number, outcome);
627	  // A TERMINAL CLOSES THE ISSUE IT STANDS ON, marked or filed, and both terminals do
628	  // (PRINCIPLES.md, owner 2026-09-06). `done` means nothing is left to act on; `rejected`
629	  // means nothing will happen. Neither is a question, so neither leaves an open issue
630	  // behind asking a person to agree with a verdict already reached — and re-asking is
631	  // what it always was, clearing the status.
632	  await api.closeIssue(gh, repo, item.number, stateReason);
633	}
634	
635	// --- CLI ----------------------------------------------------------------------
636	
637	export async function runExecutorJob() {
638	  // THE OPERATOR HOLD, FIRST ACT (PRINCIPLES.md) — before the config load, before the
639	  // first API call, so a held queue reads nothing and writes nothing rather than
640	  // deriving the world and then declining to act on it.
641	  if (isSuspended()) { console.log('## Claudinite executor\n'); console.log(suspendedNotice()); return; }
642	  const { makeGh } = await import('../world/github.mjs');
643	  const { actionRepoContext, actionsEnv, executorId, repoRoot, runUrlFor } = await import('../world/actions.mjs');
644	  const { discoverTasks } = await import('../contract/discover.mjs');
645	  const { loadConfig } = await import('../../../../engine/checks/helpers/repo-context.mjs');
646	  const { isDormant, dormancyErrors } = await import('../contract/dormancy.mjs');
647	  const { ensureLabels } = await import('../world/github.mjs');
648	  const { collectSignalsForTask } = await import('../signals/for-task.mjs');
649	  const { codeWorkRunner } = await import('./code-work-run.mjs');
650	  const { agentInvoker } = await import('../world/sessions.mjs');
651	
652	  const root = repoRoot();
653	  const { repo, defaultBranch } = actionRepoContext();
654	  if (!repo) { console.error('GITHUB_REPOSITORY not set — not in an Actions context'); process.exit(1); }
655	  const config = loadConfig(root);
656	
657	  console.log('## Claudinite executor\n');
658	  for (const e of dormancyErrors(config)) console.log(`! ${e.what} — ${e.fix}`);
659	  if (isDormant(config)) {
660	    console.log('- this project declares its scheduler dormant — nothing is picked up');
661	    return;
662	  }
663	
664	  const gh = makeGh();
665	  const { tasks, errors } = await discoverTasks(root, config);
666	  for (const e of errors) console.log(`! ${e.what}`);
667	  await ensureLabels(gh, repo, QUEUE_LABELS);
668	
669	  const runUrl = actionsEnv().GITHUB_RUN_ID
670	    ? `${actionsEnv().GITHUB_SERVER_URL ?? 'https://github.com'}/${repo}/actions/runs/${actionsEnv().GITHUB_RUN_ID}`
671	    : null;
672	
673	  const done = await runExecutor({
674	    gh, repo, root, config, tasks,
675	    executorId: actionsEnv().CLAUDINITE_EXECUTOR_ID || `actions-${actionsEnv().GITHUB_RUN_ID ?? 'local'}`,
676	    runUrl,
677	    collectSignalsFor: collectSignalsForTask({ gh, repo, root, config, defaultBranch }),
678	    runTaskCodeWork: codeWorkRunner({ root, repo, defaultBranch }),
679	    invokeAgent: agentInvoker({ repo, config }),
680	    heldNow: liveSuspendReader(gh, repo, { log: console.log }),
681	  });
682	
683	  console.log(done.length
684	    ? done.map((d) => `- #${d.issue}: ${d.outcome}`).join('\n')
685	    : '- nothing ready to pick up');
686	}
687	
688	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
689	  runExecutorJob().catch((e) => { console.error(e); process.exit(1); });
690	}
