// The executor loop end to end against a fake GitHub — pick, claim, evaluate,
// code-work, hand off, converge. The pure rules are tested beside this; what this
// pins is that the SHELL actually drives them to a terminal state, which is the
// thing a fixture over the rules alone can never say.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { runExecutor } from '../../src/execute/loop.mjs';
import { parseWorkItemBody } from '../../src/items/work-item.mjs';
import { normalizeTaskDeclaration } from '../../src/contract/task-contract.mjs';
import { makeClock } from '../sim/world/clock.mjs';
import { makeGithub } from '../sim/world/github.mjs';

const SCHEDULE = { dailyHour: 4, weeklyDay: 'Sun', monthlyDay: 1 };
const CONFIG = { taskScheduler: SCHEDULE, packConfig: {} };

// The shared fake GitHub (`test/sim/world/github.mjs`), seeded at the instant
// this file's `drive` runs at, so the timestamps it stamps agree with the `now`
// the executor is handed. Every fault it can inject is off: this file is about
// the shell driving its rules to a terminal state, and a platform misbehaving is
// a scenario's subject, not a unit test's.
const fakeRepo = (issues = [], pulls = []) => makeGithub({
  clock: makeClock({ start: '2026-08-14T04:20:00Z' }), issues, pulls,
});

const workItem = (number, task, labels, body = null) => ({
  number, title: `[claudinite-work] p/${task}`, labels,
  body: body ?? `packs/p/tasks/${task}/task.md\n\nExecute the Claudinite task above.\n`,
  created_at: '2026-08-14T04:00:00Z', updated_at: '2026-08-14T04:00:00Z',
});

// `taskDir` is a REAL directory: the executor probes it before it runs anything,
// because a task can be deleted out from under an item this run already queued.
// `gate` is how a fixture states its verdict: the declarative expression is the
// only precondition mechanism, so a fixture that must decline (or throw) does it
// through a task-local term, exactly as a real task would.
const term = (holds) => new Map([['gate', { signals: [], holds }]]);
const RUNS = term(() => ({ holds: true }));
const task = (id, decl = {}, terms = RUNS) => ({
  pack: 'p', id, taskDir: process.cwd(), taskPath: `packs/p/tasks/${id}/task.md`,
  decl: normalizeTaskDeclaration({ id, frequency: 'daily', agent_model: 'sonnet', preconditions: ['gate'], expected_outcome: 'fresh_pr', ...decl }),
  terms,
});

// `random` is pinned ascending so a fixture with several pickable items picks the
// FIRST one it lists — production's draw is random (PRINCIPLES.md) and a test that let it
// vary would be a coin flip, not a test.
const ascendingDraw = () => { let n = 0; return () => (n += 1) / 1000; };

const drive = (repo, tasks, over = {}) => runExecutor({
  gh: repo.gh, repo: 'o/r', root: '/tmp', config: CONFIG, tasks,
  executorId: 'E1', now: () => new Date('2026-08-14T04:20:00Z'), random: ascendingDraw(),
  collectSignalsFor: async () => ({}),
  runTaskCodeWork: async () => ({ ok: true, agentRequested: false }),
  invokeAgent: async () => ({ ok: true, sessionId: 's-1' }),
  log: () => {},
  ...over,
});

// --- the target (PRINCIPLES.md) ---------------------------------------------------
// The executor decides which branch and pull request the run works on ONCE, after
// the precondition's go and before code-work, and both phases are handed the
// answer: code-work as environment, the agent as item fields.

test('code-work is handed the target the executor resolved, minted under the task\'s prefix', async () => {
  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])]);
  const seen = [];
  await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 })], {
    runTaskCodeWork: async (t, { target }) => { seen.push(target); return { ok: true, agentRequested: false }; },
  });
  assert.equal(seen.length, 1);
  assert.equal(seen[0].mode, 'fresh');
  assert.match(seen[0].branch, /^claudinite\/p\/a\/2026-08-14-[a-z0-9]+$/);
  assert.ok(!repo.state.calls.some((c) => /\/pulls/.test(c)), 'a fresh_pr target reads no pull request');
});

test('a supersede run closes the pull requests it was told to, once its own exists', async () => {
  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])], [{ number: 3, head: { ref: 'claudinite/p/a/2026-08-13-old', sha: 'x' } }]);
  await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60, expected_outcome: 'supersede_existing_pr' })], {
    resolveTargetFor: async () => ({ mode: 'fresh', branch: 'claudinite/p/a/2026-08-14-new', pr: null, supersedes: [3], landed: null, reason: 'r' }),
    runTaskCodeWork: async () => ({ ok: true, agentRequested: false, delivered: ['PR: #7 (open)'], openPr: 7, deliveredPr: 7 }),
  });
  assert.equal(repo.findPull(3).state, 'closed');
  assert.match(repo.findPull(3).comments.at(-1).body, /#7/);
  assert.ok(repo.find(1).labels.includes('task:status:needs-human-approval'));
});

test('a supersede run that delivered no pull request leaves the incumbents where they were', async () => {
  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])], [{ number: 3, head: { ref: 'claudinite/p/a/2026-08-13-old', sha: 'x' } }]);
  await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60, expected_outcome: 'supersede_existing_pr' })], {
    resolveTargetFor: async () => ({ mode: 'fresh', branch: 'claudinite/p/a/2026-08-14-new', pr: null, supersedes: [3], landed: null, reason: 'r' }),
    runTaskCodeWork: async () => ({ ok: true, agentRequested: false }),
  });
  assert.equal(repo.findPull(3).state, 'open');
  assert.equal(repo.find(1).state, 'closed');
});

// The previous delivery had concluded green and was never landed. Resolution
// lands it, and that IS this occurrence: the tree the run holds predates the
