// THE FAKE AGENT INVOCATION — the routine fire, with the trichotomy the whole
// hand-off design turns on.
//
// It stands in for `src/world/sessions.mjs`: `port` carries exactly that
// module's names, and the scenario levers hang off the harness beside it.
//
// ONLY `agentInvoker` IS FAKED, because only `agentInvoker` reaches outside.
// `resolveEndpoint` and `firePayload` are config reading and prose composition —
// no world edge at all — and the two constants are ours, so all four come
// straight from the real port. A fake that re-spelled them would be a second
// implementation of something nobody needed faked, and would go on agreeing with
// itself after the real one changed.
//
// THE THREE OUTCOMES ARE NOT THREE DEGREES OF THE SAME THING:
//
//   fired       a session exists, and this module starts it on the clock
//   refused     the endpoint ANSWERED and said no — no session, ever
//   unanswered  nothing came back. A session may or may not have started, and
//               `started` is the fake's private truth about which — the thing
//               the executor cannot see and must never guess at.

import {
  DEFAULT_ENDPOINT, DEFAULT_HEADERS, firePayload, resolveEndpoint,
} from '../../../src/world/sessions.mjs';

export function makeSessions({ clock, agents = null, repo = 'o/r' } = {}) {
  const fired = [];
  // Scripted answers, consumed one per invocation; an empty script fires.
  const pending = [];
  let seq = 0;

  const port = {
    DEFAULT_ENDPOINT,
    DEFAULT_HEADERS,
    resolveEndpoint,
    firePayload,
    agentInvoker: ({ repo: slug = repo, config } = {}) => async function invoke({ task, item, nonce }) {
      // The configuration faults are the real port's own, decided before any
      // call, so they are read from the real resolver rather than scripted here.
      const endpoint = resolveEndpoint(config, task);
      if (endpoint.error) return { ok: false, answered: true, error: endpoint.error };

      const scripted = pending.shift() ?? { kind: 'fire' };
      const record = {
        at: clock.ms(), repo: slug, item: item.number, nonce, task: task?.id ?? null,
        text: firePayload({ repo: slug, item, nonce }), kind: scripted.kind,
      };
      fired.push(record);

      if (scripted.kind === 'refuse') {
        return { ok: false, answered: true, error: scripted.error ?? `endpoint "${endpoint.name}" returned 401` };
      }
      if (scripted.kind === 'unanswered') {
        // The far side may have taken it. When it did, the session runs — which
        // is exactly the world the executor cannot distinguish.
        if (scripted.started && agents) agents.start({ task, item, nonce });
        return { ok: false, answered: false, error: scripted.error ?? `endpoint "${endpoint.name}" gave no answer: socket timeout` };
      }
      const sessionId = `s-${(seq += 1)}`;
      record.sessionId = sessionId;
      if (agents) agents.start({ task, item, nonce, sessionId });
      return { ok: true, sessionId, sessionUrl: `https://claude.ai/code/${sessionId}` };
    },
  };

  const harness = {
    port,
    fired: () => fired,
    // The endpoint answers with an error status: no session exists, and no
    // retry can change that.
    refuseNext: (error = null) => { pending.push({ kind: 'refuse', error }); return harness; },
    // Nothing comes back. `started` is whether the far side took it anyway.
    leaveNextUnanswered: ({ started = false, error = null } = {}) => {
      pending.push({ kind: 'unanswered', started, error });
      return harness;
    },
  };
  return harness;
}
// SCRIPTED AGENTIC WORK — what happens after a hand-off.
//
// There is no `src/world/agents.mjs` to stand in for: an agent session is not an
// edge the engine calls, it is a thing the engine STARTS and then never hears
// from again. So this module has no port and no parity row; it exists because a
// scenario has to be able to say what the session did.
//
// A SESSION IS A SCRIPT, NOT A MODEL. The script's body is an ordinary function
// handed the fake GitHub and the item, so a scenario that wants the real
// converge calls `src/session/`'s own code from inside it and the harness
// neither knows nor cares. What this module owns is only what the session costs
// and how it ends: how many virtual minutes it takes, whether it beats while it
// runs, and whether it finishes at all.
//
// A DEAD SESSION IS SILENCE, not an error: the body never runs, nothing is
// written, and the item is left exactly as the hand-off left it. That is the
// whole input to the janitor's agent leash, and a fake that reported a death
// would be handing the engine a signal production does not have.

import { MINUTE } from './clock.mjs';

const HEARTBEAT_MARKER = '<!-- claudinite-heartbeat -->';

export function makeAgents({ clock, github, repo = 'o/r', defaultScript = {} } = {}) {
  const scripts = new Map();   // task id -> script
  const sessions = [];
  const records = [];          // whatever a session "printed"

  const scriptFor = (task) => scripts.get(task?.id ?? null)
    ?? scripts.get(`${task?.pack}/${task?.id}`)
    ?? scripts.get('*')
    ?? defaultScript;

  function start({ task, item, nonce, sessionId = null }) {
    const s = {
      id: sessionId ?? `s-${sessions.length + 1}`,
      item: item.number, task: task?.id ?? null, nonce,
      startedAt: clock.ms(), endedAt: null, dead: false, beats: 0,
    };
    sessions.push(s);

    const { minutes = 45, heartbeatMinutes = null, dies = false, run = null } = scriptFor(task);
    const endsAt = s.startedAt + minutes * MINUTE;

    if (heartbeatMinutes) {
      for (let t = s.startedAt + heartbeatMinutes * MINUTE; t < endsAt; t += heartbeatMinutes * MINUTE) {
        clock.at(t, () => {
          const issue = github.find(item.number);
          if (!issue) return;
          github.port.comment(null, repo, item.number, `${HEARTBEAT_MARKER}\nagent session \`${s.id}\` is working.`);
          s.beats += 1;
        });
      }
    }

    clock.at(endsAt, async () => {
      s.endedAt = endsAt;
      if (dies) { s.dead = true; return; }
      if (run) {
        await run({
          github, clock, repo, item, task, nonce, session: s,
          print: (line) => records.push({ at: clock.ms(), session: s.id, line }),
        });
      }
    });
    return s;
  }

  const harness = {
    start,
    sessions: () => sessions,
    records: () => records,
    // `'*'` is every task; a task id wins over it.
    script: (taskId, script) => { scripts.set(taskId, script); return harness; },
  };
  return harness;
}
// A PERSON'S ACTIONS, as events.
//
// No `src/world/humans.mjs` to stand in for, and there never will be: a person
// is not something the engine calls. They are the other writer on the same
// issues, which is the whole reason the mechanism arbitrates at all — so the
// harness needs them to be schedulable at an instant, exactly like a cron fire.
//
// Every action writes through the GitHub fake's PORT, not into its arrays: a
// person marking an issue and the engine reading it back have to go through the
// same store, or a scenario proves a world where the two never met. The one
