// THE PRECONDITION SEAM — the one call that turns a discovered task plus its
// collected signals into a verdict, and the window arithmetic a verdict is judged
// over. Contract rather than stage: both stages ask it (the scheduler run at the
// anchor, the executor again at pick), and what it means is fixed by the
// declaration, not by who is asking.

import { periodMs } from '../items/anchors.mjs';
import { taskCadence } from './task-contract.mjs';
import { evaluatePreconditions } from './precondition-policy.mjs';

export const DAY_MS = 86400e3;
export const SLACK_MS = 3600e3;

// The window a task reads with no run of its own to measure from: its cadence
// term's period, a day where it states none.
export function defaultWindowMs(task) {
  const cadence = taskCadence(task?.decl);
  if (cadence?.kind === 'due') return periodMs(cadence.cadence) + SLACK_MS;
  if (cadence?.kind === 'elapsed') return cadence.ms + SLACK_MS;
  return DAY_MS + SLACK_MS;
}

// The lookback in DAYS a verdict is judged over — what a term needs when its
// dimension carries an age rather than a windowed flag of its own (the
// conversation-logs branch reports how old its newest capture is, not whether one
// landed). Read off the collected bundle, which is where the window was decided.
export const windowDaysOf = (task, signals) => signals?.runs?.window?.days ?? defaultWindowMs(task) / DAY_MS;

// Run one task's precondition. THE only place a precondition is ever called, so a
// test that drives this drives what production drives — a precondition first
// written to take `{ signals }` passed its own direct-call test and threw on every
// real run, which is the failure this seam exists to make impossible.
//
// One form comes through here: the declarative `preconditions` expression, which
// is the only gate a task may declare (#1617). It fails LOUD by construction — a
// term that throws, an unknown name, an unreadable signal all return `{ error }`,
// a run failure the caller parks rather than a decline taken on a guess.
export function evaluatePrecondition(task, signals, packConfig = {}, item = null, at = null, schedule = null) {
  return evaluatePreconditions({
    preconditions: task.decl.preconditions,
    signals,
    config: packConfig,
    item,
    terms: task.terms,
    // The window the signals were collected over, read off the bundle where it
    // was decided (src/signals/for-task.mjs).
    windowDays: windowDaysOf(task, signals),
    // The repo's anchor settings, which a `due:` term resolves its cadence on.
    schedule,
    // The instant this verdict is for — the same one the signals were collected
    // for, so a clock-reading term and a windowed one cannot disagree about when
    // "now" is.
    now: at,
  });
}
// Reading the queue. One rule, and it is load-bearing: the work-item list comes
// from the ISSUES list API, never the search index. Search is eventually
// consistent (S6/F11), and a family list that misses a just-created item is
// exactly how a second standing item — a double execution — gets minted.

import { STATUS_DONE, isQueueItem, labelNames, statusOf } from './work-item.mjs';
import { listOpenIssuesPage, listClosedIssuesPage } from '../world/github.mjs';

// Republished beside the listings that apply it, which is where every reader of
// the queue looks for it.
export { isQueueItem };


const project = (i) => ({
  number: i.number,
  title: i.title,
  body: i.body ?? '',
  state: i.state,
  labels: labelNames(i),
  created_at: i.created_at,
  closed_at: i.closed_at ?? null,
  updated_at: i.updated_at,
});

// Every OPEN work item, oldest first. The whole queue is a page or two: a repo's
// standing items are one per scheduled task, plus whatever ad-hoc work exists.
export async function listOpenWorkItems(gh, repo) {
  const out = [];
  for (let page = 1; ; page += 1) {
    const { status, json } = await listOpenIssuesPage(gh, repo, page);
    if (status !== 200 || !Array.isArray(json) || json.length === 0) break;
    for (const i of json) {
      if (i.pull_request) continue;
      if (!isQueueItem(i)) continue;
      out.push(project(i));
    }
    if (json.length < 100) break;
  }
  return out;
}

// Every work item that converged DONE, newest first — the closed half of the queue,
// and the only evidence the superseded-park rule (janitor rule E) runs on.
//
// BOUNDED, unlike the open list: a long-lived repo's closed set is thousands of
// issues and the rule only ever asks "did this task run clean since <park>". Two
// pages of most-recently-updated is far past the horizon of any park worth closing,
// and a park older than that is stale for reasons this rule is not the fix for.
export async function listDoneWorkItems(gh, repo, { pages = 2 } = {}) {
  const out = [];
  for (let page = 1; page <= pages; page += 1) {
    const { status, json } = await listClosedIssuesPage(gh, repo, page);
    if (status !== 200 || !Array.isArray(json) || json.length === 0) break;
    for (const i of json) {
      if (i.pull_request) continue;
      if (!isQueueItem(i)) continue;
      if (statusOf(i) !== STATUS_DONE) continue;
      out.push(project(i));
    }
    if (json.length < 100) break;
  }
  return out;
}
// THE PICK ORDER over the open queue — which ready item a worker takes next, and
// which ones it must skip. It sits with the items rather than with either caller
// because BOTH stages ask it: the executor to choose what to claim, and the
// scheduler run to count what is pickable before it spends an executor invocation
// on an empty queue.
//
// The order (docs/PRINCIPLES.md): urgent first, then RANDOM among the ready, with
// two skip rules read live at pick time. Random rather than oldest-first because
// nothing leans on FIFO aging — the stale-ready escalation is period-scale — while
// a deterministic order lets one unlucky head dominate every run of a chain.
//
//  - SAME-TITLE MUTEX (S15/F6): skip an item whose exact title has another open
//    item executing or handed to an agent — one task, one execution at a time,
//    while a fan-out's distinct qualifiers still parallelize.
//  - THE `after` YIELD (S23): skip a scheduled item whose task declares `after:
//    [T]` while T's standing item is live THIS CYCLE (ready / executing / agent).
//    A declined upstream holds nothing back — it has no item at all (a no files
//    nothing, PRINCIPLES.md) — and neither does one sitting `needs-human`: a broken
//    upstream must not halt its dependents indefinitely.

import {
  URGENT, STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT, isStatus,
  parseWorkItemTitle, parseWorkItemBody, isStandingItem, hasLabel,
} from './work-item.mjs';

export const titleOf = (item) => (item.title ?? '').trim();
