// does. Decoded, never a literal label test: the item may wear any engine's spelling.
export const running = (item) => isStatus(item, STATUS_RUNNING_EXECUTOR) || isStatus(item, STATUS_RUNNING_AGENT);
// WHICH TASK AN ITEM NAMES. A filed `[claudinite-work]` item says so in its title;
// a marked issue (PRINCIPLES.md) keeps its own human title and names its task in the
// machine block's first line, so the id comes from the task whose worker path that
// is. `pathTo` is that lookup, injected because only the run holds the task set.
export const taskIdOf = (item, pathTo = () => null) => {
  const p = parseWorkItemTitle(item.title);
  if (p) return `${p.pack}/${p.task}`;
  return pathTo(parseWorkItemBody(item.body).taskPath) ?? null;
};

// The pick order (PRINCIPLES.md): urgent first, then RANDOM among the ready, with
// two skip rules read live at pick time. Random rather than oldest-first because
// nothing leans on FIFO aging — the stale-ready escalation is period-scale — while
// a deterministic order lets one unlucky head dominate every run of a chain
// (PRINCIPLES.md).
//
//  - SAME-TITLE MUTEX (S15/F6): skip an item whose exact title has another open
//    item executing or handed to an agent — one task, one execution at a time,
//    while a fan-out's distinct qualifiers still parallelize.
//  - THE `after` YIELD (S23): skip a scheduled item whose task declares `after:
//    [T]` while T's standing item is live THIS CYCLE (ready / executing / agent).
//    A declined upstream holds nothing back — it has no item at all (a no files
//    nothing, PRINCIPLES.md) — and neither does one sitting `needs-human`: a broken
//    upstream must not halt its dependents indefinitely.
//
// `open` is every open work item; `taskAfter(id)` gives a task's declared
// upstreams as `<pack>/<task>` ids, and `scheduledOf(id)` whether that task is
// asked by the scheduler at HEAD (`isScheduledTask`; null where the repo no longer
// carries it) — which is half of what says whether an item is a standing
// occurrence or an ad-hoc run (PRINCIPLES.md). `random` is the tie-break draw, injected
// so a test can pin an order the production call deliberately does not have.
export function pickOrder(open = [], { taskAfter = () => [], scheduledOf = () => null, random = Math.random, pathTo = () => null } = {}) {
  const idOf = (item) => taskIdOf(item, pathTo);
  const live = (item) => [STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT].some((s) => isStatus(item, s));
  const standing = (item) => isStandingItem(item, scheduledOf(idOf(item)));
  const liveUpstream = (upstreamId) => open.some((o) =>
    idOf(o) === upstreamId && standing(o) && live(o));
  // One draw per item, taken once: a comparator that called `random()` per
  // comparison would not be a consistent ordering, and `Array.sort` on one is
  // free to produce anything at all.
  const draw = new Map(open.map((i) => [i.number, random()]));

  return open
    .filter((i) => isStatus(i, STATUS_READY))
    .filter((i) => !open.some((o) => o.number !== i.number && titleOf(o) === titleOf(i)
      && running(o)))
    .filter((i) => {
      if (!standing(i)) return true;
      return !taskAfter(idOf(i)).some(liveUpstream);
    })
    .sort((a, b) =>
      (hasLabel(b, URGENT) ? 1 : 0) - (hasLabel(a, URGENT) ? 1 : 0)
      || draw.get(a.number) - draw.get(b.number));
}
// Anchors — when a cadence's occurrence falls (docs/PRINCIPLES.md).
//
// The arithmetic lives in `calendar.mjs`; this module exposes exactly the two
// questions asked of it — "which occurrence is current" (what a `due:` term
// measures a task's run history against) and "when is the next one" (what the
// dashboard renders) — plus the period a cadence repeats on, and the period a
// TASK keeps, read off its own cadence term.
//
// Pure and stateless: `now` is always injected, every value is UTC.

import { anchorInstant, normalizeFrequency, cadenceOf } from '../contract/calendar.mjs';

const HOUR_MS = 3600e3;
const DAY_MS = 24 * HOUR_MS;

// One period of a cadence word (`daily`, `weekly`, `monthly` — and the retired
// `frequency` field's values, `manual` having none), in ms — the unit the
// janitor's stale-ready rule counts in (PRINCIPLES.md) and the coarse step
// `nextAnchor` walks.
export function periodMs(frequency) {
  // Normalized like `anchorInstant`. Today this changes no answer — every retired token maps to
  // `daily`, which is also the fallthrough below — so it is insurance, not the thing carrying the
  // behaviour: it is what keeps this correct if `LEGACY_FREQUENCIES` ever gains a mapping that is
  // not `daily`. What DOES carry it is the door plus that fallthrough, and why it matters is
  // sharp: this feeds the janitor's stale-ready bound and the precondition's signal window, so a
  // token resolving to an HOUR here parks a member's task needs-human on every sweep (PRINCIPLES.md).
  const freq = normalizeFrequency(frequency);
  if (freq === 'weekly') return 7 * DAY_MS;
  if (freq === 'monthly') return 31 * DAY_MS;
  if (freq === 'manual') return null;
  return DAY_MS;
}

// The period a TASK keeps, read off the cadence term its declaration states: a
// `due:` cadence's period, a `last-run-over:` duration, and null for a task with
// no cadence term (asked at every tick, it runs on movement or when woken).
export function taskPeriodMs(decl) {
  const cadence = cadenceOf(decl?.preconditions);
  if (cadence?.kind === 'due') return periodMs(cadence.cadence);
  if (cadence?.kind === 'elapsed') return cadence.ms;
  return null;
}

// The most recent occurrence at or before `now`, as a Date. `manual` has none —
// nothing schedules it — so null is the whole answer.
export const mostRecentAnchor = anchorInstant;

// The earliest occurrence strictly after `now` — what a rolled item is stamped
// with. Derived by walking `mostRecentAnchor` forward rather than by adding a
// period: monthly anchors are not a fixed distance apart, and a `daily-2h` whose
// instant wraps to the previous calendar day is exactly the case a fixed add gets
// wrong. The coarse step is under one period, so the loop advances by at most two
// steps and never overshoots an occurrence.
export function nextAnchor(frequency, schedule, now) {
  if (normalizeFrequency(frequency) === 'manual') return null;
  const from = mostRecentAnchor(frequency, schedule, now).getTime();
  const step = normalizeFrequency(frequency) === 'monthly' ? 28 * DAY_MS : periodMs(frequency);
  for (let t = from + step; ; t += step) {
    const candidate = mostRecentAnchor(frequency, schedule, new Date(t));
    if (candidate.getTime() > from) return candidate;
  }
}
// APPLYING a status transition — the write half of the vocabulary whose read half
// is `work-item.mjs`'s decode (docs/PRINCIPLES.md, the migration of #1119).
//
// One rule, and it is why this is not a plain `swapLabel`: the item may wear ANY
// engine version's spelling of the status it is leaving. A member's items outlive
// its converges, so an item filed as `task:ready` is picked up by an engine that
// writes `task:status:waiting-for-executor`, and a swap that named one spelling
// would leave the other standing — an item wearing two live statuses, which is the
// torn state the janitor exists to repair.
//
// Writes stay granular (add and remove named labels, never a set-write): with
// several executors and a scheduler run moving labels at once, a set-write from a
// stale snapshot clobbers a concurrent transition (PRINCIPLES.md).
// The removes are UNCONDITIONAL — every spelling of the status being left, not
// only the ones the caller's snapshot shows. A caller holds the labels it read
// before its own earlier transitions, so filtering on that snapshot would skip
// exactly the label this engine just wrote; removing a label an issue does not
// carry 404s, which is the end state asked for and therefore success.
import { spellingsOf } from './work-item.mjs';

// Move `item` out of `fromStatus` (canonical — every spelling of it goes) and into
// the label `to`, which is whatever spelling this engine writes.
export async function swapStatus(api, gh, repo, item, fromStatus, to) {
  await clearStatus(api, gh, repo, item, fromStatus);
  return api.addLabel(gh, repo, item.number, to);
}

// Leave a status without entering another — the close path, where the terminal
// label is applied separately.
export async function clearStatus(api, gh, repo, item, status) {
  for (const label of spellingsOf(status)) {
    await api.removeLabel(gh, repo, item.number, label);
  }
}
// The queue's leases and bounds, in one place because three surfaces must agree
// on them (docs/PRINCIPLES.md): the scheduler run reclaims on the executing leash,
// the janitor sweeps on the agent leash and the stale bounds, and the task
// contract rejects at author time any code-work whose declared timeout reaches the
// executing leash (F17 — a code-work reclaimed while alive livelocks its item).
//
// The vendored workflows carry the fourth agreement, and the heartbeat reframed
// it (PRINCIPLES.md): what must hold is HEARTBEAT INTERVAL < EXECUTING LEASH, so a
// holder that is alive is never reclaimed, rather than a run cap short enough to
// kill a hung runner before its claim is reaped. The cap bought the guarantee
// that a zombie's code-work never ran beside its replacement's; what carries that
// now is code-work's own re-entrancy requirement, since a partitioned runner can
// keep working while its beats fail to post.

// A dead executor claim is reclaimed after this much silence — the holder's own
// silence, measured from its last claim or heartbeat (#924), never the issue's
// `updated_at`. Long work is legal; a holder that stops beating is not alive.
export const EXECUTING_LEASH_MS = 60 * 60e3;

// An agent session silent this long is declared dead. A legitimately longer run
// must comment on its item to reset the activity clock — stated as an assumption
// rather than discovered as an incident.
export const AGENT_LEASH_MS = 3 * 3600e3;

// An item nothing picked up for this many of its own periods leaves the queue for
// triage; a blocked item whose blockers never resolve is surfaced (comment only)
// after this long.
export const STALE_READY_PERIODS = 2;
export const STUCK_BLOCKED_MS = 2 * 86400e3;

