    // period on the survivor (SCENARIOS F32), and a hand-closed item stands
    // between `last-run-not-failed` and the failure park behind it.
    const unpicked = (i) => statusesOn(i).some((s) => s === STATUS_BLOCKED || s === STATUS_READY);
