        createdAt: i.created_at,
        closedAt: i.closed_at ?? null,
        state: i.state,
        status: statusOf(i),
        park: parkKindOf(i),
        outcome: outcomeOf(i),
        woken: parseWorkItemBody(i.body ?? '').woken !== null,
