// THE CONTINUATION OF A DEAD EXECUTOR RUN (docs/PRINCIPLES.md, S36).
//
// A run that dies — crash, timeout, cancellation, runner loss — never reaches its
// own re-dispatch, so without this the queue would sit until the next scheduled
// tick. The platform runs the calling job on a FRESH runner after any such death,
// and this fires that dispatch instead: the remainder drains in ~a minute, while
// the dead run's OWN item waits for the executing leash to reclaim it — nothing
// here touches that item.
//
// `continuation_depth` is the stop. A run that dies at startup — a broken engine,
// a revoked token — dies identically every time, and an unguarded continuation
// would dispatch itself for as long as that lasts. After MAX_DEPTH the chain
// stops and SAYS SO on the repo's workflow-failure issue: a queue that has quietly
// stopped draining is the one failure nothing else here would surface, since every
// individual run looks like an ordinary death.

import { pathToFileURL } from 'node:url';
import { makeGh } from '../world/github.mjs';
import { actionRepoContext, actionsEnv, EXECUTOR_WORKFLOW_FILE } from '../world/actions.mjs';
import { dispatchWorkflow } from '../world/github.mjs';
import { reportWorkflowFailure, runUrl } from './workflow-failure.mjs';

export const MAX_DEPTH = 3;

export const CHAIN_FAILURE_TITLE = 'Claudinite executor chain failed repeatedly';

// An absent, empty or unparseable depth is depth 0 — the first death in a chain.
// It must never read as a large number, which would silence the continuation
// exactly when the queue most needs it.
export const nextDepth = (raw) => {
  const n = Number(String(raw ?? '').trim());
  return (Number.isFinite(n) && n > 0 ? Math.floor(n) : 0) + 1;
};

// The decision, separated from the CLI shell so it tests against a fake `gh`.
// Resolves to the continuation it made; throws when the chain is over, which is
// what turns the calling job red.
export async function continueOrEscalate(gh, repo, defaultBranch, depth) {
  if (depth <= MAX_DEPTH) {
    const { ok, status } = await dispatchWorkflow(gh, repo, EXECUTOR_WORKFLOW_FILE, defaultBranch,
      { continuation_depth: String(depth) });
    if (!ok) throw new Error(`could not continue the chain on ${defaultBranch}: ${status}`);
    console.log(`- the executor run died — dispatched a fresh one on ${defaultBranch} (continuation ${depth} of ${MAX_DEPTH})`);
    return { continued: depth };
  }

  // The chain has died MAX_DEPTH times running: this is not one bad runner, and
  // dispatching another would spend the day proving it. Escalate to the same
  // one-open-issue surface the scheduler's own failures use, and let the next
  // scheduled tick be what tries again.
  const { issue, created } = await reportWorkflowFailure(gh, repo, {
    title: CHAIN_FAILURE_TITLE,
    body: `${MAX_DEPTH} consecutive executor runs died before finishing their item.`
      + ' The chain stops here; the next scheduled scheduler run will dispatch a fresh one.'
      + `\n\nThe last run: ${runUrl()}`,
  });
  console.log(`- ${created ? 'filed' : 'commented on'} #${issue}`);
  throw new Error(`the executor chain died ${MAX_DEPTH} times in a row — escalated`);
}

export async function runExecutorContinuation() {
  const { repo, defaultBranch } = actionRepoContext();
  if (!repo) throw new Error('GITHUB_REPOSITORY is not set');
  await continueOrEscalate(makeGh(), repo, defaultBranch, nextDepth(actionsEnv().CLAUDINITE_CONTINUATION_DEPTH));
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  runExecutorContinuation().catch((e) => { console.error(e.message ?? e); process.exit(1); });
}
// THE ESCALATION SURFACE FOR A WORKFLOW THAT FAILED AS A WHOLE (docs/PRINCIPLES.md).
// A scheduled run reaches no one when it goes red — nothing is
// watching the Actions tab — so a run-level failure becomes a human-visible
// issue instead.
//
// ONE OPEN ISSUE, by a fixed title: create-or-comment, so a week of nightly
// failures is one thread rather than seven issues. The labels are ensured
// FIRST, because a first-run failure may precede any other label-ensure and
// GitHub 422s the write that applies an unknown label.
//
// The platform reporting its own failure IS an origin (`task:origin:github`),
// parked in the `failure` lane — the one a person diagnoses (#1119).
//
// This lives in the engine rather than in the workflows that call it because
// `.github/workflows/` is the one path a converge cannot push into: a member's
// copy of a workflow moves only through a PR a human merges, while this module
// converges nightly like the rest of the engine.

import { pathToFileURL } from 'node:url';
import { makeGh } from '../world/github.mjs';
import { actionRepoContext, runUrl } from '../world/actions.mjs';
import { ensureLabels, createIssue, comment } from '../world/github.mjs';
import { ORIGIN_GITHUB, STATUS_NEEDS_HUMAN_FAILURE } from '../items/work-item.mjs';
import { searchIssues } from '../world/github.mjs';

// Not a queue label: this one marks the issue as the platform's own failure
// report rather than a work item, so it is defined here beside its only writer.
export const WORKFLOW_FAILURE = 'workflow-failure';

export const FAILURE_LABELS = Object.freeze([
  { name: WORKFLOW_FAILURE, color: 'b60205', description: 'Claudinite scheduler: a scheduler run or task failed' },
  { name: ORIGIN_GITHUB, color: 'd4c5f9', description: 'Claudinite queue: filed by the platform itself — a workflow reporting its own failure' },
  { name: STATUS_NEEDS_HUMAN_FAILURE, color: 'b60205', description: 'Claudinite queue: parked — the run broke, diagnose and fix' },
]);

// The open issue carrying exactly `title`, or null. Lowest number wins, so a past
// race that left two converges on the first and the duplicate stays inert.
//
// A search that does not answer returns null rather than throwing: filing a
// second issue is untidy, losing the failure report entirely is not.
export async function findOpenFailureIssue(gh, repo, title) {
  const want = title.trim();
  const q = encodeURIComponent(`repo:${repo} is:issue is:open in:title "${want}"`);
  const { status, json } = await searchIssues(gh, q);
  if (status !== 200 || !Array.isArray(json?.items)) return null;
  const exact = json.items
    .filter((i) => (i.title ?? '').trim() === want)
    .sort((a, b) => a.number - b.number);
  return exact.length ? exact[0].number : null;
}

export async function reportWorkflowFailure(gh, repo, { title, body }) {
  await ensureLabels(gh, repo, FAILURE_LABELS);
  const open = await findOpenFailureIssue(gh, repo, title);
  if (open != null) {
    await comment(gh, repo, open, body);
    return { issue: open, created: false };
  }
  const { number } = await createIssue(gh, repo, {
    title, body, labels: FAILURE_LABELS.map((l) => l.name),
  });
  return { issue: number, created: true };
}

// The URL of the run doing the reporting, republished here because the failure
// report is where every caller of it wants it.
export { runUrl };

export const SCHEDULER_FAILURE_TITLE = 'Claudinite scheduler run failed';

// The scheduler workflow's `report-failure` job. It runs only when the scheduler
// run or its drain went red, so it files unconditionally.
export async function runWorkflowFailureReport() {
  const { repo } = actionRepoContext();
  if (!repo) throw new Error('GITHUB_REPOSITORY is not set');
  const gh = makeGh();
  const { issue, created } = await reportWorkflowFailure(gh, repo, {
    title: SCHEDULER_FAILURE_TITLE,
    body: `The Claudinite scheduler run/drain run failed: ${runUrl()}`,
  });
  console.log(`- ${created ? 'filed' : 'commented on'} #${issue}`);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  runWorkflowFailureReport().catch((e) => { console.error(e); process.exit(1); });
}

