630	
631	  if (ops.some((o) => o.kind === 'create' || o.kind === 'adopt')) await ensureLabels(gh, repo, QUEUE_LABELS);
632	  // The mark is ensured whenever the mode can run here at all, not only when
633	  // something was marked: `task:origin:ad-hoc` is the entry point, and a label that
634	  // does not exist is one nobody can find in the issue's label picker.
635	  if (tasks.some((t) => `${t.pack}/${t.id}` === REQUEST_TASK_ID)) {
636	    await ensureLabels(gh, repo, QUEUE_LABELS.filter((l) => ORIGIN_LABELS.includes(l.name)));
637	  }
638	
639	  // WHAT THIS RUN ITSELF LEFT READY. The gate below reads the queue back from
640	  // GitHub, and that read is eventually consistent — it can miss an item created
641	  // milliseconds earlier (#1340). The run does not need the read to know what it
642	  // wrote, so every issue it readies is recorded here and counted regardless.
643	  const readied = new Set();
644	  // WHAT THIS RUN ITSELF FILED, in the shape `listWorkItems` projects. The forced
645	  // wake below plans over the same eventually-consistent read, where a miss is not
646	  // a skipped dispatch but a SECOND standing item beside the one just filed (#1979).
647	  const minted = [];
648	
649	  for (const op of ops) {
650	    if (op.kind === 'create') {
651	      const res = await createIssue(gh, repo, { title: op.title, body: op.body, labels: op.labels });
652	      if (res.number) {
653	        if (op.labels.includes(READY)) readied.add(res.number);
654	        minted.push({ number: res.number, title: op.title, body: op.body, state: 'open', labels: op.labels });
655	        console.log(`- created #${res.number} ${op.pack}/${op.task} [${op.labels.join(' ')}]`);
656	      } else console.log(`! could not create the work item for ${op.pack}/${op.task}: ${res.status}`);
657	    } else if (op.kind === 'ready') {
658	      await swapStatus({ addLabel, removeLabel }, gh, repo, { number: op.issue }, STATUS_BLOCKED, READY);
659	      readied.add(op.issue);
660	      console.log(`- readied #${op.issue}`);
661	    } else if (op.kind === 'reclaim') {
662	      // The reclaim comment is also the EPISODE BOUNDARY: every claim before it is
663	      // dead, and arbitrating over dead claims makes one outrank every future live
664	      // claimant — the item then livelocks through reclaim cycles forever (F18).
665	      await comment(gh, repo, op.issue, `${EPISODE_MARKER}\n${op.reason}`);
666	      await swapStatus({ addLabel, removeLabel }, gh, repo, { number: op.issue }, STATUS_RUNNING_EXECUTOR, op.to);
667	      if (op.to === READY) readied.add(op.issue);
668	      console.log(`- reclaimed #${op.issue} -> ${op.to}`);
669	    } else if (op.kind === 'adopt') {
670	      // THE ISSUE IS THE ITEM, so adoption writes to it rather than filing anything:
671	      // the machine block first, the status second. That order is what makes a torn
672	      // adoption safe — a block with no status is re-adopted by the next scheduler
673	      // run (which rewrites it), while a status with no block would name no task.
674	      const res = await setIssueBody(gh, repo, op.request, op.body);
675	      if (res.status !== 200) {
676	        console.log(`! could not adopt #${op.request}: its body could not be written (${res.status})`);
677	        process.exitCode = 1;
678	        continue;
679	      }
680	      if (op.origin) await addLabel(gh, repo, op.request, op.origin);
681	      await addLabel(gh, repo, op.request, op.status);
682	      await comment(gh, repo, op.request,
683	        `Queued: a run of \`${op.task}\` for this issue${op.model ? `, at the \`${op.model}\` family` : ''}.\n\n`
684	        + (op.blockedBy.length
685	          ? `It is **blocked** on ${op.blockedBy.map((n) => `#${n}`).join(', ')} — it enters the queue once they close.\n\n`
686	          : '')
687	        + (op.notBefore ? `It waits until ${op.notBefore} before entering the queue.\n\n` : '')
