content.content:
1	// The two operator levers (docs/PRINCIPLES.md), which are the whole of
2	// urgency, forcing, fan-out and retry:
3	//
4	//   create-work-item <pack>/<task> [--urgent] [--context …] [--not-before ISO]
5	//                                  [--blocked-by #N,#M] [--qualifier text]
6	//                                  [--supersedes #N]
7	//   create-work-item --wake <#N> [--urgent]
8	//
9	// FORCING A SCHEDULED TASK IS WAKING ITS STANDING ITEM — strip `task:blocked`,
10	// clear `Not-before`, optionally add `task:urgent`. The same lever as the human
11	// re-queue out of `needs-human`, which is no accident: "run this now" and "retry
12	// this now" are the same operation on the same object. The executor still
13	// evaluates the precondition at pick, so a force that finds no work SAYS so where
14	// the operator reads it. The slot scheduler's whole forcing apparatus — its override
15	// bag, the forced-verdict path, the `~f` slot marker and the watermark exclusion —
16	// reduced to these two levers and was deleted (#974).
17	//
18	// FORCING AD-HOC WORK IS CREATING AN ITEM — a parameterized run, an unscheduled
19	// task's run, a fan-out target. Ad-hoc is STRUCTURAL (PRINCIPLES.md): an unscheduled
20	// task is never asked by the scheduler, and a qualified title is a different title
21	// from the standing one — so such an item is invisible to the scheduler run's
22	// guards in both directions, neither suppressing the next occurrence nor consuming
23	// it. Which is why an UNQUALIFIED item for a scheduled task is refused below: it
24	// would BE that task's standing item, and the scheduler run's dedupe would close
25	// one of the two. Every item made here is stamped `Woken:` — it exists because
26	// somebody asked, which is what the cadence terms read.
27	
28	import { pathToFileURL } from 'node:url';
29	import {
30	  READY, BLOCKED, URGENT, TASK_OBSOLETE, QUEUE_LABELS, ORIGIN_MANUAL,
31	  EPISODE_MARKER, workItemTitle, workItemBody, withNotBefore, withWoken, statusesOn,
32	} from '../items/work-item.mjs';
33	import { clearStatus } from '../items/apply-status.mjs';
34	import { isScheduledTask } from '../contract/task-contract.mjs';
35	import { repoRoot } from '../world/actions.mjs';
36	import { nowIso } from '../world/clock.mjs';
37	import { setIssueBody } from '../world/github.mjs';
38	
39	// The Context a hand-created item carries when the operator names none. Generic
40	// on purpose — it names the mechanism, not the task — because an item's Context is
41	// the agent's binding scope, and a forced item that carried none would read as a
42	// scope of nothing.
43	export const FORCED_CONTEXT =
44	  'Created by hand — no precondition asserts there is work to do. Do only what the task file specifies, and converge to a no-op if there is nothing.';
45	
46	export function parseArgs(argv) {
47	  const out = { urgent: false, context: [], blockedBy: [], notBefore: null, qualifier: null, supersedes: null, wake: null, target: null };
48	  for (let i = 0; i < argv.length; i += 1) {
49	    const a = argv[i];
50	    const next = () => argv[++i];
51	    if (a === '--urgent') out.urgent = true;
52	    else if (a === '--wake') out.wake = Number(String(next()).replace('#', ''));
53	    else if (a === '--context') out.context.push(next());
54	    else if (a === '--not-before') out.notBefore = next();
55	    else if (a === '--qualifier') out.qualifier = next();
56	    else if (a === '--supersedes') out.supersedes = Number(String(next()).replace('#', ''));
57	    else if (a === '--blocked-by') out.blockedBy.push(...String(next()).split(',').map((s) => Number(s.trim().replace('#', ''))).filter(Boolean));
58	    else if (!a.startsWith('--')) out.target = a;
59	  }
60	  return out;
61	}
62	
63	// Wake an item: clear its wait and put it back in the queue. Also the sanctioned
64	// road back from `needs-human` — nothing MECHANICAL ever re-queues a triage item,
65	// and the next pickup re-runs the precondition, which is what makes the retry safe
66	// even when the failed run half-did its work.
67	export async function wakeItem(gh, repo, number, { urgent = false } = {}) {
68	  const api = await import('../world/github.mjs');
69	  const issue = await api.readIssue(gh, repo, number);
70	  if (!issue) return { ok: false, error: `#${number} could not be read` };
71	  // `Woken:` is what lets the task's cadence terms hold at the next pick — the wake
72	  // stands in for the cadence (docs/PRINCIPLES.md) — while everything else it requires
73	  // still applies; a wake is the one write that stamps it.
74	  const body = withWoken(withNotBefore(issue.body ?? '', null), nowIso());
75	  if (body !== issue.body) await setIssueBody(gh, repo, number, body);
76	  // The episode boundary: every claim before this moment is dead, and arbitrating
77	  // over dead claims is what livelocks an item through reclaim cycles forever.
78	  await api.comment(gh, repo, number, `${EPISODE_MARKER}\nWoken by hand — cleared \`Not-before\` and returned this item to the queue.`);
79	  // Every status the item wears goes, in every spelling — a wake takes the item
80	  // back from whatever held it, and a park half-cleared (the state gone, its kind
81	  // still standing) is the torn shape the janitor would have to repair.
82	  for (const status of statusesOn(issue)) await clearStatus(api, gh, repo, issue, status);
83	  await api.addLabel(gh, repo, number, READY);
84	  if (urgent) await api.addLabel(gh, repo, number, URGENT);
85	  return { ok: true, number };
86	}
87	
88	// `scheduled` is whether the task is asked by the scheduler (its declared
89	// `trigger`), null where the caller does not know.
90	export async function createWorkItem(gh, repo, { pack, task, taskPath, scheduled = null, opts, log = console.log }) {
91	  const api = await import('../world/github.mjs');
92	  const { listOpenWorkItems } = await import('../items/read.mjs');
93	  const title = workItemTitle({ pack, task, qualifier: opts.qualifier });
94	
95	  // An unqualified item for a SCHEDULED task is that task's standing item by
96	  // construction, not a run beside it — the scheduler run would treat the pair as duplicate
97	  // standing items and close the younger. The two levers that do what the operator
98	  // meant are named rather than guessed at.
99	  if (scheduled === true && !opts.qualifier) {
100	    return { ok: false, error: `${pack}/${task} is on the schedule, so an unqualified item for it IS its standing item — the scheduler run would close one of the two as a duplicate. To run it now, wake its standing item (\`--wake #N\`, or the scheduler workflow's \`wake\` input); to run it beside the schedule, give this item a \`--qualifier\` naming what makes it a different run.` };
101	  }
102	
103	  // The pick-time mutex means a new item QUEUES behind an open twin rather than
104	  // running beside it, and the operator should know they are queueing, not jumping.
105	  const twin = (await listOpenWorkItems(gh, repo)).find((i) => (i.title ?? '').trim() === title);
106	  if (twin) log(`! #${twin.number} is an open item with this exact title — the new item will queue behind it, not run beside it`);
107	
108	  await api.ensureLabels(gh, repo, QUEUE_LABELS);
109	  const blocked = opts.notBefore !== null || opts.blockedBy.length > 0;
110	  const res = await api.createIssue(gh, repo, {
111	    title,
112	    body: workItemBody({
113	      taskPath,
114	      notBefore: opts.notBefore,
115	      blockedBy: opts.blockedBy,
116	      context: opts.context.length ? opts.context : [FORCED_CONTEXT],
117	      // Created by hand: the cadence terms hold on it.
118	      woken: nowIso(),
119	    }),
