  sim.run('2026-08-12T00:00Z', '2026-08-12T08:00Z');

  assert.equal(asks(sim, 'tidy/tidy-issues').filter((e) => e.t === T('2026-08-12T04:17Z')).length, 0,
    'the open minted item held the lane — the 04:17 tick never asked');
