  closed.at('2026-08-18T09:03Z', (s) => { req2 = s.markIssue({ author: 'owner' }); });
  closed.at('2026-08-18T09:17:20Z', (s) => s.closeRequestIssue(req2.number));
  closed.run('2026-08-18T09:00Z', '2026-08-18T18:00Z');
