// A person creating a work item through the issue UI. Deliberately not the
// `create-work-item` lever, which refuses an unqualified item for a scheduled
// task: a write-gated person can always open the issue by hand, and that the
// mutex still serializes such a twin is exactly what some scenarios are about.
createItem(taskId, { urgent = false, notBefore = null, blockedBy = [], qualifier = null, eventLost = false, woken = null } = {}) {
  const task = taskOf(taskId);
  const [pack, ...rest] = taskId.split('/');
  const blocked = notBefore !== null || blockedBy.length > 0;
  const adHoc = qualifier !== null || (task && task.decl.trigger !== 'schedule');
  const created = github.seedIssue({
    title: workItemTitle({ pack, task: rest.join('/'), qualifier }),
    body: workItemBody({
      taskPath: task ? task.taskPath : `packs/${pack}/tasks/${rest.join('/')}/task.md`,
      notBefore: notBefore === null ? null : new Date(notBefore).toISOString(),
      blockedBy,
      woken: woken === null ? null : new Date(woken).toISOString(),
    }),
    labels: [adHoc ? ORIGIN_MANUAL : ORIGIN_PLANNED, blocked ? BLOCKED : READY, ...(urgent ? [URGENT] : [])],
  });
  if (!blocked) deliverLabelEvent(eventLost);
  return view(created);
},

