+  // The previous occurrence of a task's cadence, for the steady-state seed.
+  function previousOccurrence(task, t0) {
+    const due = (task.decl.preconditions ?? []).map((e) => /^due:(\w+)/.exec(e)).find(Boolean);
+    const over = (task.decl.preconditions ?? []).map((e) => /^last-run-over:(\d+)([hd])/.exec(e)).find(Boolean);
+    if (due) {
+      const anchorHour = CONFIG.taskScheduler.dailyHour;
+      const d = new Date(t0);
+      let a = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate(), anchorHour);
+      if (a > t0) a -= DAY;
+      if (due[1] === 'weekly') { while (new Date(a).getUTCDay() !== 0 || a > t0) a -= DAY; }
+      if (due[1] === 'monthly') {
+        const d2 = new Date(a);
+        a = Date.UTC(d2.getUTCFullYear(), d2.getUTCMonth(), 1, anchorHour);
+        if (a > t0) { const b = new Date(a); a = Date.UTC(b.getUTCFullYear(), b.getUTCMonth() - 1, 1, anchorHour); }
+      }
+      return a;
+    }
+    if (over) return t0 - Number(over[1]) * (over[2] === 'h' ? HOUR : DAY);
+    return t0 - DAY;
+  }
+
   return sim;
 }

input.old_string:
  // Seven hours blocked is normal under this cadence and must read as normal — an
  // escalation here would park every deferred item the queue holds.
  assert.equal(sim.log.filter((e) => e.kind === 'escalate').length, 0);
});

