// The pick has to skip a quarantined item, and the only place the harness can
// say so is the listing the executor picks from.
const listOpen = github.port.listOpenIssuesPage;
github.port.listOpenIssuesPage = async (...args) => {
  const res = await listOpen(...args);
  if (!quarantined.size || !Array.isArray(res.json)) return res;
  return { ...res, json: res.json.filter((i) => !quarantined.has(i.number)) };
};

