// A quarantined item is one NO EXECUTOR EVER CLAIMS — a member whose runner is
// broken, from the queue's point of view. It is hidden from the listing an
// EXECUTOR RUN picks from and from nothing else: the janitor's stale-ready rule
// exists precisely to notice such an item, so hiding it from the sweep too would
// be hiding the thing under test.
const listOpen = github.port.listOpenIssuesPage;
