1	// THE HARNESS — the fake world of `world/` wired to the real queue, and nothing
2	// else. It holds no model of the mechanism: every verdict a scenario asserts on
3	// was reached by the code under `src/`, driven here against an in-memory GitHub,
4	// a virtual clock and a scripted set of agent sessions.
5	//
6	// WHAT IT OWNS is a world and a cast:
7	//
8	//  - THE WORLD is `world/`: the clock and its event queue, the GitHub store, the
9	//    Actions ledger, the invocation endpoint, the agent sessions and the people.
10	//    Each of those modules says what it models and what it does not.
11	//  - THE CAST is the scenario's tasks. A scenario states a task the way a
12	//    declaration does — a cadence term, an `after`, whether it has a work step and
13	//    how long it takes — plus a `precondition` function standing for every
14	//    condition a real declaration would name in terms of its own signals. That
15	//    function is loaded as a TASK-LOCAL TERM (`gate`), so the real precondition
16	//    engine evaluates it in the real expression, in the real two passes.
17	//  - THE LEVERS are what a person does: marking an issue, creating an item,
18	//    re-queueing a park, forcing a task, holding the queue. Each one drives the
19	//    real path a person's action takes — a label edit through the GitHub port, a
20	//    wake through the scheduler workflow's own `wake` input.
21	//
22	// WHAT IT DOES NOT OWN is any answer. There is no scheduler here, no pick order,
23	// no claim arbitration and no anchor arithmetic: `schedulerRun`, `runExecutor`,
24	// `sweepQueue`, `continueOrEscalate` and `convergeOps` are imported and run. When
25	// a scenario and the engine disagree, the disagreement is the finding — which is
26	// the whole reason this file may not contain a second opinion.
27	//
28	// THE LOG is an OBSERVATION, not a state machine: `record` is called where the
29	// harness itself acts (a workflow starts, a lever is pulled) and where the engine
30	// hands back what it decided (`asked`, the ops, the janitor's result), plus a
31	// classification of the WRITES the engine made, read off the GitHub store as they
32	// land. Nothing in it is computed from a rule.
33	
34	import { existsSync } from 'node:fs';
35	import { fileURLToPath } from 'node:url';
36	
37	import { makeClock, MINUTE, HOUR, DAY } from './world/clock.mjs';
38	import { makeGithub } from './world/github.mjs';
39	import { makeActions } from './world/actions.mjs';
40	import { makeAgents } from './world/agents.mjs';
41	import { makeSessions } from './world/sessions.mjs';
42	import { makeHumans } from './world/humans.mjs';
43	
44	import { ENDPOINTS_KEY } from '../../../../engine/checks/helpers/repo-context.mjs';
45	import { installClock } from '../../src/world/clock.mjs';
46	import { SCHEDULER_WORKFLOW_FILE, EXECUTOR_WORKFLOW_FILE } from '../../src/world/actions.mjs';
47	import { isSuspended, SUSPEND_ALL_VAR } from '../../src/world/hold.mjs';
48	import { schedulerRun } from '../../src/schedule/run.mjs';
49	import { dispatchDrain } from '../../src/schedule/drain-dispatch.mjs';
50	import { runExecutor } from '../../src/execute/loop.mjs';
51	import { continueOrEscalate, nextDepth } from '../../src/recover/continuation.mjs';
52	import { sweepQueue } from '../../tasks/task-janitor/queue-sweep.mjs';
53	import { convergeOps, refusal } from '../../src/session/converge-item.mjs';
54	import { normalizeTaskDeclaration } from '../../src/contract/task-contract.mjs';
55	import { validatePreconditions } from '../../src/contract/precondition-policy.mjs';
56	import { collectSignalsForTask } from '../../src/signals/for-task.mjs';
57	import { EXECUTING_LEASH_MS } from '../../src/items/leases.mjs';
58	import { HEARTBEAT_MS, HEARTBEAT_MARKER } from '../../src/items/heartbeat.mjs';
59	import { REQUEST_TASK_ID, REQUEST_TASK, BUILT_IN_PACK } from '../../src/contract/built-in-tasks.mjs';
