61	import {
62	  READY, URGENT, BLOCKED, EPISODE_MARKER, CLAIM_MARKER, HANDOFF_MARKER,
63	  STATUS_DONE, STATUS_REJECTED, STATUS_LABELS, PARK_PREFIX, STATUS_PREFIX,
64	  ORIGIN_PLANNED, ORIGIN_MANUAL, ORIGIN_AD_HOC,
65	  statusOf, isParked, parkKindOf, outcomeOf, originOf, labelNames,
66	  workItemTitle, workItemBody, parseWorkItemTitle, parseWorkItemBody, taskIdFromPath,
67	} from '../../src/items/work-item.mjs';
68	
69	export { MINUTE, HOUR, DAY };
70	export { READY, ORIGIN_AD_HOC, ORIGIN_PLANNED, ORIGIN_MANUAL, statusOf, isParked, parkKindOf };
71	
72	// A scenario's instant, in the shorthand its `at(…)` calls are written in: a bare
73	// `2026-08-12T09:03Z` is a minute, not a second.
74	export const T = (iso) => Date.parse(iso.length === 17 ? iso.replace('Z', ':00Z') : iso);
75	
76	// How long after its cron instant a run actually starts. Actions does not start a
77	// scheduled run at the minute it was asked to, and a latency of zero is the one
78	// value that is certainly wrong — so a scenario naming the instant a tick HAPPENED
79	// says `tick('…04:17Z')` rather than transcribing the delay.
80	export const START_LATENCY_MS = 40_000;
81	export const tick = (iso) => T(iso) + START_LATENCY_MS;
82	
83	// The park label of a kind, for a scenario naming one.
84	export const NH = (kind) => `${PARK_PREFIX}${kind}`;
85	
86	const REPO = 'o/r';
87	const DEFAULT_BRANCH = 'main';
88	// The checkout the run reads tasks out of. The executor probes a task's directory
89	// before it spawns anything, so this has to be a real one — and this folder is the
90	// only directory a harness can be sure of.
91	const ROOT = fileURLToPath(new URL('.', import.meta.url));
92	
93	// The whole of what a fake session costs, in the shape the invoker's config takes.
94	const CONFIG = Object.freeze({
95	  taskScheduler: {
96	    dailyHour: 4,
97	    weeklyDay: 'Sun',
98	    monthlyDay: 1,
99	    [ENDPOINTS_KEY]: { default: { url: 'https://example.invalid/fire', tokenSecret: 'CCR_TOKEN' } },
100	  },
101	  packConfig: {},
102	});
103	
104	// A run that dies the way a runner dies: no exception a caller could handle, no
105	// labels written, nothing said. The executor's promise simply never returns, which
106	// is what leaves the item wearing its claim for the leash to reclaim.
107	class RunnerDied extends Error {}
108	
109	// The two triggers a `workflow_dispatch` of the executor can carry, told apart by
110	// the input the continuation job sets. A dispatch with no depth is the scheduler
111	// run's drain job.
112	const triggerOf = (fired) => (fired?.inputs?.continuation_depth ? 'failure-redispatch' : 'scheduler-run-drain');
113	
114	export function makeSim({
115	  tasks = [],
116	  schedulerRunMinute = 17,
117	  // The UTC hours the cron fires on — `null` is the every-hour grid. A member's
118	  // real cron names its hours explicitly, and what that costs and delays is the
119	  // question the cadence scenarios ask.
120	  cronHours = null,
121	  executingLeashMs = EXECUTING_LEASH_MS,
122	  heartbeatMinutes = HEARTBEAT_MS / MINUTE,
123	  heartbeatsDisabled = false,
124	  pickSeed = 1,
125	  collaborators = { owner: 'admin' },
126	  // How long after the cron instant the runner actually starts, and how long after
127	  // a dispatch. Actions starts neither at the instant it was asked to.
128	  startLatencyMs = START_LATENCY_MS,
129	} = {}) {
130	  // The one wiring relation the engine states (F17, reframed): a beat that does not
131	  // sit inside the leash arrives too late to keep a live holder out of the reclaim.
132	  // Refused here rather than discovered mid-scenario, because a world wired that way
133	  // livelocks and every assertion over it is about the wiring, not the mechanism.
134	  if (heartbeatMinutes * MINUTE >= executingLeashMs) {
135	    throw new Error(`heartbeat interval (${heartbeatMinutes}m) reaches the executing leash — F17 (reframed)`);
136	  }
137	
138	  const clock = makeClock({ start: 0 });
139	  const github = makeGithub({ clock, repo: REPO, collaborators });
140	  const agents = makeAgents({ clock, github, repo: REPO });
141	  const sessions = makeSessions({ clock, agents, repo: REPO });

