+  const seen = [];
+  const it = () => own(sim, 'tidy/tidy-issues')[0];
+  sim.at('2026-08-12T04:18:00Z', () => seen.push(labelsOf(it())));  // filed at the tick's ask
+  sim.at('2026-08-12T04:18:30Z', () => seen.push(labelsOf(it())));  // claimed by the drain
